  @override
  String get adderallReferenceDay1 =>
      '苯丙胺戒断：早期会发生什么\n\n来源：MedlinePlus（美国国家医学图书馆）\n\n什么是苯丙胺？\n苯丙胺是一类兴奋剂，既包括非法物质（例如俗称“speed”的非法苯丙胺），也包括用于治疗ADHD和发作性睡病的处方药（例如Adderall和Vyvanse）。它们会显著提高多巴胺和去甲肾上腺素水平，从而可能带来强烈的专注、精力和欣快感。长期大量使用后，大脑会适应这些反复的激增，因此停用后情绪、精力和动力可能会暂时下降。\n\n常见戒断症状\nMedlinePlus列出的典型苯丙胺停用症状包括：\n• 对药物的强烈渴求\n• 从抑郁、烦躁到焦虑的情绪波动\n• 整天感到疲倦\n• 无法集中注意力\n• 幻觉（看到或听到并不存在的东西）\n• 头痛、身体酸痛、食欲增加以及睡眠不佳等身体反应\n\n戒断危险吗？\nMedlinePlus并未把苯丙胺戒断本身描述为具有医学危险性，但指出严重症状可能需要住院式治疗；苯丙胺使用造成的情绪和心理问题（包括抑郁）也可能很严重，需要支持。\n\n寻求帮助\nMedlinePlus建议，如果你或你认识的人对苯丙胺成瘾并需要帮助停止使用，应联系医疗服务提供者。如果出现自伤想法，它会引导读者使用988或911等危机支持资源。';

  @override
  String get adderallReferenceDay3 =>
      '苯丙胺戒断管理：第3天\n\n来源：世界卫生组织（2009）《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，NCBI Bookshelf\n\n第3天处于什么阶段\nWHO指南指出，兴奋剂戒断症状“在最后一次使用兴奋剂后的24小时内开始，并持续3–5天”。第3天正处于这一急性期，通常也是症状开始缓解前最艰难的几天之一。\n\n症状\n对于苯丙胺类兴奋剂，指南列出：\n• 烦躁和易怒\n• 抑郁\n• 睡眠和食欲增加\n• 肌肉酸痛\n大量使用的人还可能出现精神病性症状，例如偏执、思维紊乱或幻觉。\n\n主要是心理层面的挑战\n与酒精或阿片类药物戒断不同，兴奋剂戒断通常不会带来呕吐、震颤或癫痫发作。主要困难在心理层面——情绪低落、快感缺失，以及与多巴胺功能暂时低下有关的渴求。\n\n管理方式\nWHO指南建议支持性护理：\n• 每天至少饮用2–3升水\n• 补充含B族维生素和维生素C的复合维生素\n• 对疼痛和焦虑进行对症用药\n• 严重烦躁时先采用行为策略，仅在需要时使用地西泮镇静\n\n急性期之后\n指南指出，最严重的戒断只持续几天，之后会进入较轻的恢复期，可持续一到两个月。';

  @override
  String get adderallReferenceDay7 =>
      '停用Adderall一周：最糟的阶段正在过去\n\n来源：Li & Shoptaw，《Clinical Management of Psychostimulant Withdrawal: Review of the Evidence》，Addiction（2023），PubMed Central\n\n急性期结束\n这篇证据综述把精神兴奋剂戒断分为几个阶段。在急性期，症状“在最初2–3天后达到高峰”，而这些症状造成的“主要不适通常会在4–7天内消退”。第一周结束时，大多数人已经度过崩溃期最难熬的部分——精力和食欲开始稳定，睡眠也开始恢复规律。\n\n接下来会怎样\n综述指出，大多数残余症状会在接下来的两到三周继续缓解。到了第7天，恢复已经明显展开。\n\n第7天仍可能存在的症状\n心理症状通常比身体上的崩溃感持续更久：\n• 动力不足和快感缺失\n• 难以集中注意力\n• 情绪仍低于平常水平\n这些反映了多巴胺系统正在重新调整，是恢复过程中正常且暂时的一部分。\n\n恢复信号\n目前没有FDA批准的药物专门治疗兴奋剂戒断，因此这一阶段主要依靠支持性护理、规律生活、睡眠、营养和心理支持。';

  @override
  String get adderallReferenceDay14 =>
      '停用Adderall两周：进入较长期恢复阶段\n\n来源：世界卫生组织（2009）《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，NCBI Bookshelf\n\n已过急性期\nWHO认为兴奋剂戒断最严重的阶段大约持续3–5天，之后是约一到两个月的较轻恢复期。到两周时，崩溃期已经明显过去。\n\n较长期恢复期是什么感觉\n嗜睡、烦躁和肌肉酸痛大多已经缓解。剩下的通常较轻：情绪低落或波动、动力下降，以及随着大脑奖励系统重新调整而间歇出现的渴求。\n\n睡眠和食欲\n急性期增加的睡眠和食欲正在恢复正常。随着睡眠稳定，情绪、注意力和精力往往也会跟着改善。\n\n复用风险与ADHD\n这仍是复用风险较高的时期，尤其是停药后原有的ADHD症状重新出现时。WHO指南强调心理支持和预防复用的技能；对于因ADHD服用Adderall的人，这是与医生讨论非兴奋剂方案或替代治疗的好时机。';

  @override
  String get adderallReferenceDay30 =>
      '停用Adderall一个月：大多数症状已在身后\n\n来源：Li & Shoptaw，《Clinical Management of Psychostimulant Withdrawal: Review of the Evidence》，Addiction（2023），PubMed Central\n\n一个月处于什么阶段\n综述发现，大多数戒断症状会在最初两到三周逐渐减退。到30天时，大部分症状已经缓解，情绪和动力通常也比第一周好得多。\n\n后期恢复阶段\n从一个月到六个月，记忆、计划、专注和决策能力会继续改善。到一个月时，崩溃期已经结束，这些进步也已经开始。\n\n情绪和动力\n崩溃期深重的快感缺失此时大多已经减轻。随着自然多巴胺信号恢复，第一周令人毫无乐趣的活动会重新开始带来满足感。\n\n对于ADHD患者\n如果Adderall原本用于治疗ADHD，基础症状现在可能更加明显。在这个阶段，与医疗服务提供者一起制定非兴奋剂策略或替代方案很重要。';

  @override
  String get adderallReferenceDay60 =>
      '停用Adderall两个月：较长期恢复期接近尾声\n\n来源：世界卫生组织（2009）《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，NCBI Bookshelf\n\n两个月处于什么阶段\nWHO描述了初始崩溃后持续约一到两个月的较轻恢复期。到了60天，你已处于这一窗口的末端，残余症状大多正在消退。\n\n哪些方面会改善\n指南列出的兴奋剂戒断症状——烦躁、抑郁情绪以及睡眠和食欲紊乱——对大多数人来说已经显著缓解：\n• 平常情绪更稳定，早期恢复时的波动减少\n• 睡眠和食欲恢复正常\n• 奖励系统更容易对日常愉悦作出反应——食物、运动、人际联系\n\n恢复信号\n剂量更高、使用时间更长会让恢复需要更多时间，而持续停用会让情绪、动力和清晰思维在接下来的几个月继续向正常状态靠近。\n\n身体健康\n随着药物从日常生活中消失，兴奋剂对心率、食欲和体重的影响减弱，使用兴奋剂造成的心血管负担也随之减轻。';

  @override
  String get adderallReferenceDay90 =>
      '停用Adderall三个月：最糟阶段已过，恢复仍在继续\n\n来源：Li & Shoptaw，《Clinical Management of Psychostimulant Withdrawal: Review of the Evidence》，Addiction（2023），PubMed Central\n\n90天处于什么阶段\n三个月时，早期症状早已消失，而记忆、计划、专注、决策和奖励系统仍会继续改善。\n\n思维和记忆继续恢复\n综述发现，记忆、计划、专注以及风险决策能力可以在数月内继续改善。到了90天，只要持续停用，注意力和记忆仍在朝好的方向发展。\n\n为什么这一阶段仍然重要\n目前没有FDA批准的药物专门针对兴奋剂戒断，因此规律生活、治疗、运动、睡眠和支持是帮助恢复度过这一阶段的主要工具。现在建立这些习惯，会把恢复继续向前推进。\n\n更大的图景\n三个月是一个真实的成就——最艰难的身体和情绪阶段已经过去；只要持续停用，此后的总体轨迹就是稳步改善。';

  @override
  String get adderallReferenceDay180 =>
      '停用Adderall六个月：早已越过最难熬的阶段\n\n来源：《Withdrawal Syndromes》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\nStatPearls如何描述兴奋剂\n这份临床参考把兴奋剂恢复描述为先经历崩溃，随后逐渐改善。常见问题包括抑郁、睡得很多、饥饿感增加、情绪低落，以及动作和思维变慢。抑郁可能持续数周，之后较轻的恢复还会继续。\n\n六个月处于什么阶段\n到六个月时，你早已越过StatPearls描述的急性期和持续数周的抑郁阶段。文中所说的缓慢恢复已有充分时间推进；对大多数人来说，此时平常的情绪、睡眠、食欲和动力已经稳定可靠。\n\n恢复信号\nStatPearls描述的是最初几周之后仍会继续的渐进恢复。到六个月，急性崩溃和数周的抑郁期已经远去，稳定的情绪、睡眠、食欲和动力成为主要状态。\n\n与ADHD的关系\n对于因ADHD服用Adderall的人，停用六个月是一个适合头脑清醒地与医生回顾当前症状的时间，也可以评估运动、睡眠、规律生活、治疗或替代药物等非兴奋剂方法是否满足需要。';

  @override
  String get adderallReferenceDay365 =>
      '停用Adderall一年：实质性恢复，坦诚看待\n\n来源：Berman等，《Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review》，Molecular Psychiatry（2008），PubMed Central\n\n关于这篇综述\n这篇综述追踪高剂量或长期苯丙胺暴露可能对大脑造成的影响，并记录了停用期间可测量的恢复。\n\n关于恢复，它发现了什么\n综述记录了长期停用后脑血流以及负责回收多巴胺的蛋白质出现恢复。不同脑区恢复速度不同，但总体方向很明确：停止使用后，大脑会修复。\n\n长期恢复\n综述记录了长期停用后脑血流和多巴胺回收出现可测量的恢复。到一年时，这些脑系统已经有整整一年时间进行重建。\n\n一年时意味着什么\n对大多数人——尤其是按处方剂量服用Adderall的人——停用一年意味着奖励、注意和动力系统在日常生活中运作良好。使用量更大或持续时间更长的人可能需要更多时间，但恢复仍会继续。与恢复早期相比，复用风险已经低得多。';

  @override
  String get alcoholReferenceDay1 =>
      '停止饮酒后，你的睡眠会发生什么变化？\n\n来源：《Alcohol and the Sleeping Brain》（Colrain, Nicholas & Baker），Handbook of Clinical Neurology——同行评审，由NIH托管\n\n酒精与睡眠结构\n酒精具有镇静作用，因此会缩短入睡所需的时间，并在前半夜增加深度慢波睡眠。但这需要付出代价：酒精会抑制REM（快速眼动）睡眠——这一与记忆巩固和情绪调节相关的恢复性阶段——并在后半夜随着酒精被代谢而让睡眠变得支离破碎。\n\n停止饮酒后的第一晚\n由于酒精会抑制REM做梦睡眠，停饮后的最初几晚常常会出现REM反弹：在正常睡眠模式恢复的过程中，梦境变得生动、睡眠更浅且易断。这是恢复过程中正常且暂时的一部分。\n\n恢复开始\n随着大脑在接下来的几天到几周内重新调整，REM睡眠和整体睡眠质量都会改善。睡眠障碍是与戒断相关的最持久的症状之一，但随着持续戒酒，它会逐渐趋向正常。\n\n关于大量饮酒的提醒\n对于大量或长期每日饮酒的人，最初24小时还可能出现戒断症状（焦虑、出汗、震颤、恶心）。严重的戒断可能很危险——如果你一直每天大量饮酒，在突然停饮之前请先咨询医生。';

  @override
  String get alcoholReferenceDay3 =>
      '急性期与早期恢复\n\n来源：《Alcohol Withdrawal》，StatPearls——同行评审，NIH国家医学图书馆\n\n最初的24–72小时\nStatPearls记载，戒断症状会在最后一次饮酒后的数小时内出现——包括震颤、失眠、激越、出汗、心率和血压升高——并且症状通常在72小时左右达到高峰。到第三天结束时，大多数人已经度过急性期最严重的阶段。严重戒断（癫痫发作，或震颤性谵妄——StatPearls指出后者可能在停止或减量后长达3至5天内的任何时间点出现）属于医疗急症：每日大量饮酒者不应在未经医嘱的情况下突然停饮。\n\n渴求如潮水般涌来\n渴求常常在最初几天内加剧，但单次渴求是短暂的——通常几分钟内就会过去。认识到每一波渴求都会自行消退，能让人更容易熬过去。\n\n水分恢复\n酒精会抑制抗利尿激素（ADH），使肾脏排出更多水分，让长期饮酒者处于慢性脱水状态。一旦停止饮酒，这种利尿效应就会结束，体液平衡在最初几天开始恢复——通常表现为皮肤更清爽、精力更稳定。\n\n心神与睡眠开始安定\n随着急性期过去，被酒精扰乱的大脑化学（GABA和谷氨酸）开始重新平衡。思维清晰度改善，而在戒断早期严重破碎的睡眠也开始在第一周内趋向更好的质量。';

  @override
  String get alcoholReferenceDay7 =>
      '免疫系统如何恢复\n\n来源：《Alcohol and the Immune System》（Sarkar, Jung & Wang），Alcohol Research: Current Reviews——同行评审，由NIH托管\n\n酒精如何削弱免疫力\n酒精以多种方式削弱免疫系统。即使是一次大量饮酒，也能让抗感染能力下降长达24小时。长期饮酒会减少白细胞、扰乱免疫信号，并损害肠道和肺部防御，从而增加感染风险和伤口愈合缓慢的风险。\n\n消除伤害\n一旦停饮，其中许多影响会得到改善。白细胞和免疫信号开始恢复，肠道和气道防御也开始修复。在第一周内，你的免疫系统不再每天被打压，对常见感染的抵抗力也开始提高。\n\n一个渐进的过程\n免疫系统的完全恢复需要一周以上的时间，修复的程度取决于饮酒有多重、有多久——但停止饮酒的第一周正是重建开始的地方。';

  @override
  String get alcoholReferenceDay14 =>
      '戒酒早期的脑部恢复\n\n来源：Bartsch AJ et al.，《Manifestations of early brain recovery associated with abstinence from alcoholism》，Brain（2007）——同行评审\n\n测量恢复\n这项研究使用MRI对刚刚戒毒的酒精依赖者在戒酒的最初几周内进行随访，并与健康对照组进行比较。它捕捉到了停止饮酒后大脑在物理层面上的重建。\n\n脑容量回升\n长期饮酒会使大脑萎缩——部分是细胞体积的可逆性缩小，而不仅仅是永久性的细胞丢失。戒酒后，研究人员测得平均全脑容量增长了近2%，集中在小脑、中脑、脑室和额叶区域。这种再生长大部分发生在早期，即在停酒后的最初一两周内。\n\n小脑与注意力\n在负责运动和注意力的大脑区域，恢复尤其明显。随着注意力出现可测量的改善，脑细胞健康的标志物也同步上升，因此物理层面的愈合带来了思维上的切实进步。\n\n是基础，而非终点\n复杂推理等高级功能的恢复更为渐进，但最初两周已经证明：一旦戒酒，大脑会迅速开始愈合。';

  @override
  String get alcoholReferenceDay30 =>
      '减少饮酒后血压会下降\n\n来源：Roerecke et al.，《The effect of a reduction in alcohol consumption on blood pressure: a systematic review and meta-analysis》，Lancet Public Health（2017）——同行评审\n\n证据\n这项荟萃分析汇总了36项随机试验（约2,865名受试者），检验人们减少饮酒后血压会发生什么变化。它发现了一种明确的剂量依赖效应：减酒越多，血压下降越多。\n\n效果有多大？\n每天饮酒两杯或更少的人，减少饮酒后血压没有显著变化。超过这一阈值后，效应呈剂量依赖：在每天饮酒六杯或更多、并将饮酒量减半的人中效果最强，他们的收缩压平均下降约5.5 mmHg，舒张压平均下降约4.0 mmHg。这一幅度的下降具有临床意义——可与某些降压药相媲美，足以降低长期的中风和心脏病风险。\n\n为什么一个月很重要\n酒精通过激活应激反应、升高皮质醇并使血管僵硬来升高血压。这项综述中的试验显示，这一益处会在持续减酒的几周内显现——因此，戒酒约一个月后，较大量饮酒者的血压已经有时间向更健康的水平回落。\n\n一个阈值效应\n该综述发现了一个明确的阈值：益处集中在每天饮酒超过两杯的人身上，并且之前的饮酒量越重，益处越大。如果你饮酒较轻，就别指望获得这一特定的降压益处——但较重的饮酒者停止饮酒后，确实能获得可测量的心血管回报。';

  @override
  String get alcoholReferenceDay60 =>
      '停止饮酒后的肝脏恢复\n\n来源：美国国家酒精滥用与酒精中毒研究所（NIAAA），《Alcohol\'s Effects on the Body》\n\n酒精如何损伤肝脏\n肝脏负责处理你所饮入的大部分酒精，也首当其冲地承受损伤。NIAAA描述了酒精相关性肝损伤的进展过程：它始于脂肪肝（肝脂肪变性——脂肪在肝细胞内堆积），可能发展为酒精性肝炎（炎症），并在长期大量饮酒后发展为肝纤维化和肝硬化（瘢痕形成）。\n\n早期阶段是可逆的\n关键在于，肝脏具有极强的再生能力，而且这种损伤的早期阶段可以在停止饮酒后得到改善。尤其是脂肪肝，往往会在持续戒酒后消退。到戒酒约两个月时，肝脏已经有充足的时间清除脂肪沉积、平息炎症并恢复更健康的功能——这通常反映在下降的肝酶水平（ALT和AST）上。\n\n肝脏之外\nNIAAA指出，酒精还会给心脏、胰腺和免疫系统带来负担。让身体从酒精中获得一段持续的休息，也能让这些系统恢复——许多人到这一阶段会注意到精力更稳定、整体健康更好，正是得益于此。';

  @override
  String get alcoholReferenceDay90 =>
      '戒酒三个月后的思维与记忆\n\n来源：关于戒酒后神经心理恢复的系统综述（PubMed Central，2024）——同行评审\n\n证据表明了什么\n这项综述汇总了追踪人们停止饮酒后思维和记忆如何恢复的研究。大多数能力会在大约六到十二个月内趋向正常，其中一些会改善得更早。\n\n哪些最先改善\n有两项能力突出地早于其他能力恢复：基本处理速度（该综述发现它通常在大约一个月时恢复，尽管更复杂任务的准确性会滞后）和工作记忆更新。到大约三个月时，许多人已经注意到这些能力的提升。\n\n哪些需要更长时间\n注意力、计划、决策、冲动控制、知觉和记忆会在六到十二个月的恢复窗口期内持续改善。\n\n影响恢复的因素\n该综述指出，恢复受到年龄、吸烟状况和病前能力等因素的影响——但令人鼓舞的是，它并不始终取决于过去饮酒的总量。恢复是预期中的走向。\n\n为什么这很重要\n更清晰的思维就是实实在在的康复：更好的注意力和决策能力有助于人们坚持治疗并避免复发。';

  @override
  String get alcoholReferenceDay180 =>
      '戒酒六个月时的大脑恢复\n\n来源：关于物质使用期间戒断过程中大脑结构和功能恢复的同行评审综述（PubMed Central）\n\n恢复仍在继续\n最初几周的早期脑容量回升只是开始。这项综述记载，随着持续戒酒，大脑在结构和功能上都会继续恢复——灰质得以恢复，受损的、负责协调脑区之间通信的白质通路也会在数月内得到修复。\n\n大脑前部\n大脑前部的恢复尤为重要，它负责判断、计划和自我控制。随着它愈合，决策能力和冲动控制也会增强。\n\n大脑的重塑与功能\n除了物理层面的修复，大脑的功能和连接也在恢复。大脑能够重塑和重新学习，这使得持续戒酒成为进行心理治疗和养成新习惯的强有力时期。\n\n恢复信号\n到六个月时，大脑的结构和功能都明显在向更健康的正常状态迈进。保持戒酒会让这种恢复有更多时间继续累积。';

  @override
  String get alcoholReferenceDay365 =>
      '酒精、癌症风险与停止饮酒\n\n来源：美国国家癌症研究所（NCI），《Alcohol and Cancer Risk》\n\n酒精会致癌\nNCI指出，科学界存在强烈共识：饮酒可以致癌。酒精与口腔（口腔癌）、咽部（喉咽）、喉部（声带）、食道、肝脏、乳腺以及结肠和直肠的癌症相关。饮酒越多、时间越长，风险就越高。\n\n酒精如何驱动癌症\n其机制包括：乙醛——酒精的一种有毒分解产物，会损伤DNA；氧化应激和炎症；对保护性营养素吸收的损害；以及就乳腺癌而言，雌激素水平升高。\n\n停止饮酒后风险会下降\n重要的是，NCI报告称，随着时间推移，戒酒与更低的风险相关——研究表明，口腔癌和食道癌的升高风险会在停止饮酒后下降，尽管可能需要数年时间才能接近从未饮酒者的风险水平。戒酒一年是这条道路上有意义的一步。\n\n叠加的益处\n达到一年还能巩固戒酒带来的心血管和肝脏收益——血压降低、心律失常风险下降、肝脏持续愈合——以及不断下降的癌症风险。';

  @override
  String get benzodiazepineReferenceDay7 =>
      '苯二氮卓戒断：第一周\n\n来源：世界卫生组织（2009）《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，NCBI Bookshelf\n\n关于苯二氮卓戒断安全的提示\n苯二氮卓戒断可能很危险。WHO指南明确指出，最安全的做法是逐步递减苯二氮卓的用量，这“有助于缓解苯二氮卓戒断症状并预防癫痫发作”。长期使用后切勿突然停药——应与医生共同制定减量方案。\n\n戒断何时出现\nWHO的时间线取决于药物的作用时长：\n• 短效类（奥沙西泮、阿普唑仑、替马西泮）：戒断在最后一次服药后1–2天开始，持续2–4周或更久\n• 长效类（地西泮、硝西泮）：戒断在最后一次服药后2–7天开始，持续2–8周或更久\n第一周的里程碑正是这样一个时间点：即便是长效苯二氮卓，此时也已清除到足以让戒断全面显现的程度。\n\n早期戒断症状\n• 反跳性焦虑——往往比药物原本治疗的那种焦虑更强烈\n• 失眠和睡眠紊乱\n• 震颤和肌肉紧张\n• 出汗和心悸\n• 对光和声音的敏感度升高\n\n监测\nWHO指南指出，戒断的严重程度“可能剧烈波动”，因此不推荐使用正式量表；相反，临床医生应每隔几小时检查一次，给予安抚并解释症状。苯二氮卓会增强GABA——大脑主要的镇静信号；长期使用会使该系统变得迟钝，因此撤除药物后大脑会处于过度兴奋状态——这正是焦虑、震颤和癫痫发作风险的来源，也是必须逐步减量的原因。';

  @override
  String get benzodiazepineReferenceDay14 =>
      '苯二氮卓戒断：两周\n\n来源：Ashton，《Protracted withdrawal syndromes from benzodiazepines》，Journal of Substance Abuse Treatment（1991），PubMed\n\n仍处于急性戒断期\n到两周时，许多人——尤其是停用长效苯二氮卓的人——仍处于急性期，此时大脑镇静系统（GABA）与兴奋系统之间的失衡最为明显。焦虑、失眠和知觉障碍都很常见。\n\n为什么苯二氮卓戒断会迁延\nHeather Ashton教授描述了最初的戒断症状如何演变成更持久的问题。焦虑、失眠、思维不清晰和感觉变化可能持续数月，因为大脑的耐受性改变逆转得很慢。\n\n缓慢可逆的改变\nAshton将这些描述为“中枢神经系统中缓慢可逆的功能性改变”。其核心主张是恢复：神经系统会逐步逆转长期苯二氮卓暴露所造成的那种功能性适应。\n\n逐步减量是关键\n证据有力地支持将缓慢、受监督的减量作为最安全的停药方式，让大脑逐步重新适应，而不是突然面对抑制性信号的缺失。';

  @override
  String get benzodiazepineReferenceDay60 =>
      '苯二氮卓与两个月时的睡眠恢复\n\n来源：Poyares et al.，《Chronic benzodiazepine usage and withdrawal in insomnia patients》，Journal of Psychiatric Research（2004），PubMed\n\n苯二氮卓如何改变睡眠\n苯二氮卓被广泛用于治疗失眠，但它们会改变睡眠结构。在这项多导睡眠图研究中，受试者平均每晚服用苯二氮卓近七年，慢性用药与慢波（深度）睡眠减少、浅睡眠第2阶段增多相关——因此，使用者即使感到昏昏欲睡，也会失去恢复性的深度睡眠。\n\n深度睡眠回来了\n令人鼓舞的发现是：该研究在停药15天后再次测量睡眠，发现与慢性用药的那些夜晚相比，慢波睡眠和δ活动得到恢复，同时主观睡眠质量也得到改善。被药物抑制的深度睡眠，在停药后约两周内开始恢复。\n\n这在60天时意味着什么\n如果深度睡眠能在两周内恢复，那么到两个月时，你的大脑已经有充足的时间继续重建自然的、恢复性的睡眠。早期戒断中严重的反跳性失眠通常已经平息。作者坦言，停药起初确实会加重睡眠问题——这正是逐步减量重要的原因——但到他们方案结束时，睡眠质量已经优于长期服用苯二氮卓时的水平。\n\n两个月时的其他改善\n许多早期身体戒断症状——肌肉紧张、震颤、心悸、出汗——到两个月时通常已经缓解或消失，因为身体在重新调节。';

  @override
  String get benzodiazepineReferenceDay90 =>
      '停用苯二氮卓三个月后：身体健康趋于稳定\n\n来源：Ashton，《Protracted withdrawal syndromes from benzodiazepines》，Journal of Substance Abuse Treatment（1991），PubMed\n\n身体趋于稳定\n到90天时，急性期早已过去。对于完成了规范减量的人来说，大多数身体戒断症状——震颤、心悸、头痛以及最严重的睡眠紊乱——都已大幅缓解，睡眠也普遍更加稳定。\n\n为什么有些症状会持续\nAshton记载，有些症状可能持续数月。到三个月时，残留的焦虑、脑雾和感觉变化仍可能出现，而大脑会继续其缓慢、可逆的重新调整。\n\n焦虑持续的两个原因\n1. 大脑的GABA系统仍在向正常敏感性重新适应——这是一个缓慢的过程\n2. 当初导致使用苯二氮卓的任何潜在焦虑，如今在没有药物缓冲的情况下被感知到\n\n接受心理治疗的好时机\n最严重的早期症状已经过去，三个月是一个强有力的节点，可以借助谈话疗法（如针对焦虑的认知行为疗法CBT）等支持手段，在神经系统继续安定的同时培养应对技能。';

  @override
  String get benzodiazepineReferenceDay180 =>
      '六个月时的思维与记忆：可测量的进步\n\n来源：Tata et al.，《Lack of cognitive recovery following withdrawal from long-term benzodiazepine use》，Psychological Medicine（1994），PubMed\n\n这项研究做了什么\n这项研究对21名长期服用苯二氮卓的患者进行了测试，分别在停药前、停药后不久以及戒断六个月时进行，并与匹配的对照组比较。这是苯二氮卓恢复文献中最坦率的数据点之一。\n\n它发现了什么\n在停药前，患者在言语学习、记忆、运动速度、视觉协调和视觉推理方面存在问题。停药后几乎没有什么变化。到六个月时，其中几个方面已经出现了可测量的改善。\n\n这意味着什么\n到六个月时，言语学习、记忆、运动速度和视觉协调都已出现可测量的恢复。这种改善已经很明显，而且还有继续发展的空间。\n\n更大的图景\n如果你在六个月时仍感到头脑发懵，这项研究告诉我们：这是意料之中的，坚持戒断才是前进的道路。更长期的研究显示，恢复会持续到远超这一节点——大脑会继续愈合。';

  @override
  String get benzodiazepineReferenceDay365 =>
      '停用苯二氮卓一年后：思维与记忆持续恢复\n\n来源：Barker et al.，《Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis》，Archives of Clinical Neuropsychology（2004），PubMed\n\n我们所拥有的最强证据\n研究人员汇总了在停药至少六个月后对长期苯二氮卓使用者重新进行测试的研究。汇总结果显示，戒断后思维和记忆出现了明显的恢复。\n\n好消息\n汇总研究发现，戒断后思维和记忆的多个方面出现了真实、可测量的改善。到大约一年时，与用药期间相比，这种恢复是广泛而明显的。\n\n恢复仍在继续\n汇总研究发现思维和记忆出现了广泛的恢复。到一年时，你已经沿着一条在六个月时就可测量的恢复趋势走了很远。\n\n这在一年时意味着什么\n到一年时，可以预期思维、记忆和清晰度会出现实质性恢复——大多数人会感到自己明显比用药期间更加敏锐。但如果某些方面仍显滞后，这与证据是一致的，并不意味着你停滞不前。恢复仍在继续，一年的戒断是这条道路上一个重要而有价值的里程碑。';

  @override
  String get benzodiazepineReferenceDay540 =>
      '停用苯二氮卓18个月后：缓慢但真实的恢复\n\n来源：Ashton，《Protracted withdrawal syndromes from benzodiazepines》，Journal of Substance Abuse Treatment（1991），PubMed\n\n为什么苯二氮卓恢复需要这么久\n苯二氮卓作用于GABA——大脑主要的镇静系统。长期使用会改变该系统反应的强度，而这些改变可能需要数月才能逆转。这就是为什么苯二氮卓的恢复以月而不是以周来衡量。\n\n18个月处于什么位置\nAshton描述了持续时间较长、可能需要数月才能缓解的戒断症状。到18个月时，对大多数人来说最糟糕的阶段早已过去，残留的焦虑、感觉变化和脑雾也已基本平息。\n\n缓慢可逆\n关键的是，Ashton把潜在改变描述为“中枢神经系统中缓慢可逆的功能性改变”。缓慢，但可逆——漫长的时间线反映的是苯二氮卓造成的适应之深，而非大多数人身上的永久性损伤。\n\n恢复信号\nAshton将潜在改变描述为缓慢可逆。到18个月时，大脑的镇静GABA系统已经有很长时间来安定，主导方向是持续地向正常状态恢复。';

  @override
  String get benzodiazepineReferenceDay730 =>
      '停用苯二氮卓两年后：重大而持久的进展\n\n来源：Barker et al.，《Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis》，Archives of Clinical Neuropsychology（2004），PubMed\n\n恢复中的一个里程碑\n两年是一个重要的里程碑，尤其是在经历了漫长的戒断之后。早期和残留症状阶段早已过去，第一年的成果又有一年时间来巩固。\n\n证据支持什么\n汇总研究显示，戒断后在许多方面都出现了恢复。到两年时，大多数人报告焦虑处于或低于使用苯二氮卓前的水平，无需药物即可获得可靠睡眠，情绪更稳定，思维比用药期间更清晰。\n\n恢复信号\n汇总研究证实了思维和记忆在许多方面的恢复。到两年时，持续恢复是证据所支持的可预期结果。\n\n保持正确视角\n两年为睡眠、情绪、记忆和清晰思维提供了一个漫长的恢复窗口。证据显示这四方面都有实质性改善，而且愈合会从这里继续。';

  @override
  String get benzodiazepineReferenceDay1095 =>
      '停用苯二氮卓三年后：长期愈合\n\n来源：Barker et al.，《Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis》，Archives of Clinical Neuropsychology（2004），PubMed\n\n长远视角\n三年处于苯二氮卓恢复时间线的最远端。对绝大多数人来说，即便经历过严重而漫长的戒断，破坏性症状也早已过去，与用药期间相比，生活质量发生了根本性的改变。\n\n荟萃分析发现了什么\n对长期使用者的汇总研究显示，戒断后在许多方面都出现了恢复。在数年的戒断中，主导性的故事是思维、记忆和日常功能的广泛恢复。\n\n恢复信号\n长期研究显示思维和记忆在许多方面都有恢复。到三年时，早期和残留的戒断阶段都早已远去，那些成果也有了数年时间来巩固。\n\n一条充满希望的信息\n苯二氮卓的恢复之旅是医学上最艰巨的历程之一，三年的持续愈合是一项意义深远的成就。证据是明确的：大脑会实质性愈合，大多数人恢复了清晰度、睡眠和情绪范围，而且改善会随着时间继续。';

  @override
  String get cocaineReferenceDay1 =>
      '可卡因戒断：最初24小时\n\n来源：《Withdrawal Syndromes》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\n可卡因与大脑\n可卡因会阻断大脑奖赏回路中多巴胺（以及其他单胺类物质）的再摄取，使多巴胺积聚并产生强烈的欣快感和精力。随着长期使用，大脑会通过下调这一系统来适应，因此一旦没有药物，正常的活动也会显得平淡无味。\n\n崩溃期\nStatPearls将兴奋剂戒断描述为：一旦停止使用，便从一次“崩溃”开始，其特征是显著的抑郁、过度睡眠、饥饿、情绪低落，以及运动和思维的严重迟缓。在最初24小时内，这通常包括：\n• 极度疲劳和睡眠需求增加\n• 情绪低落，运动和思维迟缓\n• 食欲增加（可卡因会抑制食欲）\n\n在更广泛的成瘾文献中，渴求、易怒和焦虑在这一窗口期也常被广泛报告，尽管StatPearls并未将它们明确列为崩溃期的一部分。\n\n与其他一些药物不同\nStatPearls指出，兴奋剂戒断可通过观察和支持性护理来处理；与酒精或苯二氮卓戒断不同，它通常不会引起癫痫发作或谵妄。主要的危险在心理层面——在崩溃期，抑郁以及（在大量使用的人中）自杀意念可能出现，因此建议给予支持和监测。\n\n没有获批的药物\n目前尚无获批用于治疗可卡因戒断的药物；处理方式是支持性的，而诸如应急管理等非药物手段，是针对潜在物质使用障碍的循证疗法。';

  @override
  String get cocaineReferenceDay3 =>
      '停用可卡因三天：应对挑战高峰\n\n来源：《Cocaine Toxicity》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\n可卡因如何影响身体\nStatPearls记载，可卡因会阻断多巴胺、去甲肾上腺素和血清素的再摄取，延长交感神经的刺激。这既是它带来欣快感的原因，也是它危险的原因——它几乎能影响每一个器官系统。\n\n第2–4天：心理戒断的高峰\n到第三天，急性崩溃期已让位于最强烈的心理戒断：\n• 情绪低落和抑郁心境达到最强烈的程度\n• 快感缺失\n• 强烈且由线索触发的渴求\n• 焦虑和坐立不安\n• 睡眠紊乱——有人睡得过多，有人失眠\n\n心血管危险正在消退\nStatPearls将心血管毒性认定为可卡因最致命的影响：心率和血压升高、心肌需氧量增加、冠状动脉痉挛以及血小板活化——这些共同驱动心律失常、心肌梗死和中风的风险，即便是年轻使用者也不例外。可卡因自身的半衰期很短，约为一小时，到第三天药物本身已完全从你的系统中清除——不过StatPearls指出，其代谢产物在使用后数小时内仍可能引起血管收缩，其中一种代谢产物可能残留数周，因此一些残留的心血管负担可能比药物本身持续更久。\n\n前方的路\n急性期很强烈，但最需要支持、也持续最久的是心理症状——抑郁、渴求和快感缺失。';

  @override
  String get cocaineReferenceDay7 =>
      '停用可卡因一周：身体恢复开始\n\n来源：《Withdrawal Syndromes》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\n急性期正在结束\nStatPearls将可卡因戒断描述为从最初的崩溃期转入更长的恢复阶段。到第一周结束时，最严重的症状通常在缓解，而多巴胺系统仍在继续重建。\n\n身体恢复正在进行\n一旦可卡因的交感神经刺激停止，它对心血管、食欲、睡眠和气道的影响就会在接下来几天到几周内开始逆转：\n• 心率和血压向正常回落\n• 食欲逐渐恢复（可卡因会强烈抑制食欲）\n• 睡眠模式开始稳定\n• 如果可卡因是经鼻吸食，鼻腔通道开始愈合\n\n心理症状仍在继续\nStatPearls指出，抑郁和快感缺失是兴奋剂戒断的特征，并且会比身体症状持续更久：\n• 情绪仍然低落，尽管不如高峰期那么严重\n• 由线索触发的渴求依然强烈\n• 注意力和动力仍然受损\n\n急性期后阶段\n此后，戒断会转入持续数周乃至数月的、在情绪、渴求和清晰思维方面更平稳的改善。了解这一规律，能让恢复中较慢的那部分变得更容易应对。';

  @override
  String get cocaineReferenceDay14 =>
      '停用可卡因两周：找到稳定\n\n来源：《Withdrawal Syndromes》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\n两周时\n到两周时，严重的崩溃症状——深度抑郁、大量睡眠以及运动和思维迟缓——通常已经缓解。此时的恢复重点转向重建大脑和情绪健康。\n\n情绪与情感状态\n到两周时，在多巴胺系统恢复期间，情绪仍可能低于正常水平。与第一周相比，深重的快感缺失正在缓解，真实的幸福感时刻正在回归。\n\n渴求与触发因素\n在这一阶段，由线索触发的渴求是一个重大挑战。大脑已在可卡因使用与特定的环境、人、情绪和活动之间形成了牢固的关联。即便总体情绪正在改善，遇到其中任何一个触发因素都可能引发强烈的渴求。避开高风险环境并建立新的关联很重要。\n\n睡眠改善\n到两周时，睡眠通常比急性戒断阶段更加稳定、更有恢复性。改善的睡眠对情绪、清晰思维以及管理渴求的能力都有显著的积极作用。\n\n打好基础\n由于针对兴奋剂使用障碍的循证疗法是行为层面的——应急管理、心理治疗和同伴支持——因此两周这个节点是接入那些将支撑长期恢复的支持结构的重要时机。';

  @override
  String get cocaineReferenceDay60 =>
      '停用可卡因两个月：情绪和奖赏开始恢复\n\n来源：《Recovering from Cocaine: Insights from Clinical and Preclinical Investigations》，Neuroscience & Biobehavioral Reviews（2013），PubMed Central\n\n大脑在做什么\n这篇综述综合了关于停止使用可卡因后大脑变化的人类和动物研究。慢性可卡因会改变多巴胺系统并降低额叶皮层的活动；这些系统的恢复，正是人们在戒断早期所注意到的情绪和动力改善的基础。\n\n奖赏系统的进展\n在动物研究中，可卡因引起的多巴胺受体和再循环蛋白的变化随着持续戒断而向健康水平回落。随着奖赏系统恢复，深重的快感缺失逐渐消散，日常的奖赏——食物、人际联系、成就——又重新让人感到满足。\n\n恢复信号\n到两个月时，情绪正在改善，睡眠更加稳定，而多巴胺和额叶皮层系统仍在继续重建。灵长类动物研究显示，可卡因相关的D1受体和转运体变化正随着持续戒断向对照水平回落。';

  @override
  String get cocaineReferenceDay90 =>
      '停用可卡因三个月：多巴胺标志物回升\n\n来源：《Recovering from Cocaine: Insights from Clinical and Preclinical Investigations》，Neuroscience & Biobehavioral Reviews（2013），PubMed Central\n\n为什么90天是一个里程碑\n这篇综述强调，三个月这个时间点在生物学上具有重要意义。在非人灵长类动物中，被可卡因升高的多巴胺D1受体和转运体，在约90天的戒断后显示出“回到对照水平的证据”——这是奖赏系统能在药物消失后重新调整的直接证据。\n\n大脑前部\n作者们强调，大脑前部的恢复是长期戒断最重要的标志之一。这一区域负责冲动控制、决策和自我控制，随着它的恢复，这些能力也会增强。\n\n90天显示了什么\n到90天时，灵长类动物研究发现D1、D2和多巴胺转运体的密度已与非用药对照组无显著差异。即便在长期暴露之后，到这一时间点，多巴胺系统的大幅恢复已清晰可见，并会随着戒断继续。';

  @override
  String get cocaineReferenceDay180 =>
      '停用可卡因六个月：思维更清晰\n\n来源：《Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies》，PubMed Central\n\n可以成像的恢复\n这篇综述汇总了纵向脑成像研究，这些研究在人们戒断时间不断延长的过程中对他们进行反复扫描。就可卡因而言，它报告称，随着持续戒断，功能活动会出现可测量的恢复。\n\n脑成像证据\n两项功能性MRI研究对可卡因使用者进行了长期追踪，两者都发现随着戒断时间延长，中脑和丘脑的激活得到改善。在其中一项中，戒断约六个月后，大脑的激活模式已与非成瘾的健康对照相当。就各类物质而言，该综述指出，核成像结果指向了戒断过程中的多巴胺能恢复。\n\n这在六个月时意味着什么\n这些功能性进步与人们在此阶段报告的真实世界改善相一致：\n• 注意力和工作记忆更好\n• 决策和冲动控制更敏锐\n• 情绪和情绪调节更稳定\n\n恢复信号\n在大约六个月时，一个纵向fMRI队列显示出与非成瘾健康对照相当的激活模式，同时随着戒断时间延长，中脑和深部脑区的激活得到改善。这是被直接成像出来的功能性大脑恢复。';

  @override
  String get cocaineReferenceDay365 =>
      '停用可卡因一年：心血管负担解除\n\n来源：《Cocaine Toxicity》，StatPearls（NCBI Bookshelf），美国国家医学图书馆\n\n为什么心脏是核心\nStatPearls将心血管毒性认定为可卡因最致命的影响。每次使用都会升高心率、血压和心肌需氧量，同时引起冠状动脉痉挛并促进血栓形成——这一组合即便在年轻人中也会驱动心脏病发作、心律失常和中风。\n\n一年的戒断解除了什么\n没有可卡因的每一天，都是摆脱这些急性伤害的一天。在一年中，反复的血压和心率飙升消失了，可卡因引起的冠状动脉痉挛和急性心肌梗死的风险被解除，心脏也不再被推向氧供需失衡。\n\n恢复信号\n停止可卡因会中止反复的冠状动脉痉挛、心动过速、高血压、血栓促进和氧供需失衡——这些正是驱动急性心脏损伤的因素。既有的纤维化或心肌炎仍是医学问题，但反复的可卡因触发伤害已经消失。\n\n大脑也在恢复\n到一年时，奖赏和自我控制系统已有足够时间恢复，从而支持更好的冲动控制、更稳定的情绪，以及对日常奖赏更强的反应。';

  @override
  String get cocaineReferenceDay730 =>
      '停用可卡因两年：持续恢复\n\n来源：《Recovering from Cocaine: Insights from Clinical and Preclinical Investigations》，Neuroscience & Biobehavioral Reviews（2013），PubMed Central\n\n长远视角\n这篇综述汇集了人类和动物研究关于长期停用可卡因的发现。其核心结论是，额叶皮层功能的保持与恢复是长期戒断最重要的标志——长期戒断者（10个月以上）比短期戒断者表现出更高的额叶皮层活动。\n\n什么在继续愈合\n• 被可卡因改变的多巴胺标志物随着持续戒断继续向正常水平靠拢\n• 在活跃使用者和戒断早期使用者身上看到的灰质和白质完整性下降，可能随着更长时间的戒断而逆转，这或许是通过持续的髓鞘成熟实现的\n• 额叶控制回路——冲动控制、判断、情绪调节——在增强\n\n恢复信号\n作者们提出了一个真诚的科学性提醒：长期戒断者之间的一些差异可能反映了一种“幸存者效应”——起初大脑完整性更好的人可能更容易保持戒断——而不仅仅是恢复本身。但清楚的是，停用可卡因两年所支持的，是一个功能上远比使用者更接近非使用者的大脑，以及一种不只是戒断、而是被实质重建的生活。';

  @override
  String get ghbReferenceDay1 =>
      'GHB戒断：最初的数小时\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n⚠ 这是医疗急症\nGHB戒断属于最危险的物质戒断之一，可与严重的酒精和苯二氮卓戒断相匹敌。若不治疗，超过一半的病例会进展为谵妄，并伴有危险的心率和血压波动以及癫痫发作。任何依赖GHB、GBL或1,4-丁二醇的人，都应寻求受监督的住院解毒，而不是独自停药。\n\n为什么它来得这么快\nGHB的半衰期只有30–60分钟，依赖者通常需要每2–3小时补一次药，才能避免戒断——比酒精或苯二氮卓快得多。正是这种快速的药代动力学，使得症状会比其他镇静催眠药的戒断更早出现。\n\n早期症状\n焦虑、失眠、震颤、出汗、心率加快和血压升高。';

  @override
  String get ghbReferenceDay3 =>
      'GHB戒断：最艰难的几天\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n最艰难的一段\n这项研究发现，几种核心戒断症状——肌肉酸痛、肌肉抽动、紧张受压感、心率加快和腹部痉挛——在最初三天最为严重，到第四天时许多症状的严重程度下降了70%以上。这一早期窗口通常是最高风险的时期，此时未经治疗的戒断最可能升级为谵妄、癫痫发作，或危险的心率和血压波动。\n\n严重特征\n• 严重的激越和焦虑\n• 幻听、幻视和偏执\n• 震颤、出汗、心跳加速和高血压\n• 癫痫发作的风险\n\n处理方式\n该研究将苯二氮卓递减和药物性GHB递减描述为两种常用的解毒方法，并指出有证据表明，GHB递减对症状的控制可能比单用苯二氮卓更有效。无论哪种方法都需要密切监测——这并不适合在家中自行处理。';

  @override
  String get ghbReferenceDay7 =>
      '停用GHB一周\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n大多数症状正在消退\n几种核心戒断症状的严重程度或发生率在最初四天内下降了70%以上。在受监督的递减治疗下，递减阶段本身平均持续11天，之后是约六天的恢复阶段——因此到一周时，许多人已经深入这一改善进程，即便整个过程尚未完全结束。\n\n可能残留的症状\n• 出汗、震颤和双手发抖\n• 睡得很多，或者反过来失眠和坐立不安\n• 渴求\n\n该研究发现，这些特定症状直到第11天变化都相对较小，因此这一周内症状持续存在并不罕见。在综合征明显平息之前，持续的医疗监督仍然重要。';

  @override
  String get ghbReferenceDay14 =>
      '停用GHB两周\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n已过急性综合征\n到两周时，该研究描述的急性身体综合征——在受监督治疗下，其递减和恢复阶段合计平均约17天——通常已经解决或非常接近解决。心率、血压和大多数身体症状应该正在趋于稳定。\n\n什么仍在残留\n该研究特别指出，一些患者在出院时渴求和失眠仍然存在，并指出这些可能促成复吸风险。即便危险的早期阶段已经过去，此时支持和规律的生活仍然很重要。';

  @override
  String get ghbReferenceDay30 =>
      '停用GHB一个月\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n一个月处于什么位置\n到一个月时，该研究描述的急性危险阶段早已过去。集中在最初几天、随后是平均约两周半的受监督递减和恢复期的急性危险阶段，此时已经远去。渴求和失眠是出院时识别出的关键残留复吸风险。\n\n为什么支持仍然有帮助\n如果到一个月时渴求、情绪低落或睡眠问题仍然存在，这与该研究作者们标记为复吸风险因素的情况是一致的——这正是持续的支持和规律生活重要的原因。';

  @override
  String get ghbReferenceDay90 =>
      '停用GHB三个月\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n三个月的恢复\n到三个月时，急性GHB戒断综合征早已解决。出院时识别出的残留风险是渴求和失眠，因此三个月的戒断让睡眠、自主神经稳定性以及防复吸的日常习惯都有了充足的时间来巩固。\n\n人们通常报告什么\n• 平时情绪更平静\n• 睡眠更可靠\n• 思维更清晰，渴求更少\n\n如果焦虑、失眠或情绪低落在三个月时仍然明显，值得与临床医生讨论，而不是想当然地认为它会自行解决。';

  @override
  String get ghbReferenceDay180 =>
      '停用GHB六个月\n\n来源：《Characterization of the GHB Withdrawal Syndrome》，PubMed Central\n\n半年之后\n到六个月时，急性GHB戒断综合征早已解决，恢复已完全从解毒转向稳定的睡眠、渴求控制和防复吸。危险的自主神经紊乱和易发谵妄的阶段属于最初几天到几周，而非这一阶段。\n\n更大的图景\n考虑到早期阶段的危险性，以及（部分由残留的渴求和失眠所驱动）复吸风险的真实存在，安全度过GHB戒断并坚持半年不碰，是一项重大的成就。把你带到这里的那套日常习惯和支持，值得继续保留。';

  @override
  String get inhalantsReferenceDay1 =>
      '停止使用吸入剂：第一天\n\n来源：Radparvar，《The Clinical Assessment and Treatment of Inhalant Abuse》，The Permanente Journal（2023），PubMed Central\n\n为什么会出现戒断\n慢性吸入剂使用会导致神经适应——神经系统开始期待这种物质。许多吸入剂作用于与酒精相同的大脑回路，因此停用会让大脑暂时失衡。这些化学物质很快从血液中清除，但会储存在体脂中，这可能使戒断出现的时间难以预测。\n\n早期症状\n这篇综述将吸入剂戒断描述为类似于酒精或苯二氮卓戒断，报告的症状包括：\n• 恶心、呕吐和出汗\n• 震颤和心率加快\n• 失眠和睡眠紊乱\n• 焦虑和易怒\n\n安全提示\n在更严重的病例中，该综述还把幻觉、妄想和癫痫发作列入了报告的症状之中，尽管它并没有给出精确的逐日时间表——请把这些当作可能出现的症状，而不是固定的时间线。在解毒期间接受医疗监督是明智的，尤其是对于大量、长期使用者。';

  @override
  String get inhalantsReferenceDay7 =>
      '停用吸入剂一周\n\n来源：Radparvar，《The Clinical Assessment and Treatment of Inhalant Abuse》，The Permanente Journal（2023），PubMed Central\n\n急性窗口\n临床文献将吸入剂戒断描述为类似于酒精或苯二氮卓戒断，但普遍认为它持续时间更短。到第一周结束时，对大多数人来说，急性身体症状——恶心、震颤、出汗、失眠——通常正在消退。\n\n什么仍在残留\n• 疲劳和脑雾\n• 情绪低落或不稳\n• 渴求\n\n关于早期戒断的说明\n这一阶段的脑雾并不意味着持久的损伤——大脑仍在重新调整。关于思维和记忆在接下来的几周到几个月里具体如何恢复的研究，将在后续里程碑中介绍。';

  @override
  String get inhalantsReferenceDay14 =>
      '停用吸入剂两周\n\n来源：Radparvar，《The Clinical Assessment and Treatment of Inhalant Abuse》，The Permanente Journal（2023），PubMed Central\n\n已过急性期\n临床综述将吸入剂戒断描述为与酒精或苯二氮卓戒断相似但更短。到两周时，恶心、震颤、失眠和焦虑通常已经平息。\n\n前方的路\n注意力、记忆、运动和协调能力会在接下来的几个月里更渐进地恢复。持续戒断会给所有这些系统改善的时间。良好的营养（吸入剂使用会消耗维生素B12）和戒断为这一切奠定了基础。';

  @override
  String get inhalantsReferenceDay30 =>
      '停用吸入剂一个月\n\n来源：Dingwall et al.，《Cognitive recovery during and after treatment for volatile solvent abuse》，Drug and Alcohol Dependence（2011），PubMed\n\n一个月处于什么位置\n早期戒断期早已过去。在这项研究中，一些学习技能在六周内得到改善，而视觉协调、记忆、计划和决策能力则在接下来的几个月里更渐进地改善。\n\n哪些可以改善\n• 注意力和一些学习任务\n• 随着身体稳定，情绪和睡眠得到改善\n• 运动速度，渐进地\n\n恢复信号\n该研究的结论很明确：记忆、计划和决策能力会在数月到数年的戒断中逐渐改善。持续戒断是这种恢复最有力的驱动力。';

  @override
  String get inhalantsReferenceDay90 =>
      '停用吸入剂三个月\n\n来源：Dingwall et al.，《Cognitive recovery during and after treatment for volatile solvent abuse》，Drug and Alcohol Dependence（2011），PubMed\n\n一个不均衡、更漫长的过程\n这项研究对完成八周治疗项目的人进行了随访，并在大约一年后对其中一些人进行了复查。一些学习技能在六周内得到改善，而视觉协调、记忆、计划和决策能力则在更长的时期内持续改善。\n\n坚持到底\n该研究显示，那些恢复较慢的技能会在数月到数年间逐渐改善。到三个月时，持续戒断仍然是月复一月积累更多恢复的最有力杠杆。';

  @override
  String get inhalantsReferenceDay365 =>
      '停用吸入剂一年\n\n来源：《A prospective study of neurocognitive changes 15 years after chronic inhalant abuse》，PubMed\n\n真实、可测量的恢复\n一项长期研究发现，在戒断两年后，慢性吸入剂相关的脑部和思维问题出现了实质性恢复。到一年时，你已经在这条恢复道路上走了很远。\n\n这意味着什么\n记忆、注意力和运动功能继续改善。长期戒断会带来真正的大脑恢复：到两年时，在没有铅所致脑损伤的慢性使用者中，大多数大脑、记忆和思维评分已恢复到正常水平。';

  @override
  String get inhalantsReferenceDay730 =>
      '停用吸入剂两年\n\n来源：《A prospective study of neurocognitive changes 15 years after chronic inhalant abuse》，PubMed\n\n两年这个节点\n这是研究中的关键里程碑：反映长期溶剂使用所致脑损伤的缺陷，在戒断两年后显示出实质性恢复。作者总结道，在没有含铅汽油所致脑损伤的情况下，长期戒断可能使正常的大脑功能得以恢复。\n\n恢复信号\n主要的例外是含铅汽油滥用造成的损伤，它可能导致持续的缺陷。除此之外，两年的戒断代表了大脑获得充分记录的、最佳的愈合机会——同时也围绕它重建了一种生活。';

  @override
  String get ketamineReferenceDay1 =>
      '停止使用氯胺酮：第一天\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug》，PubMed Central\n\n戒断主要是心理层面的\n与阿片类药物或酒精不同，氯胺酮很少产生严重的身体戒断。停用通常是安全的；人们更多是与渴求和心理依赖作斗争，而不是身体疾病。\n\n你可能会感到什么\n• 情绪波动和情绪低落\n• 渴求\n• 偶尔出汗或心悸\n\n关键一步\n对任何有膀胱症状的人来说，立即并彻底停止使用是康复的必要起点——因此第一天是所有决定中最重要的一个。';

  @override
  String get ketamineReferenceDay7 =>
      '停用氯胺酮一周\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review》，PubMed Central\n\n心理阶段\n停用氯胺酮早期的主要挑战是心理层面的：渴求、情绪改变或低落，以及一些脑雾。身体戒断即便出现，通常也很轻微。\n\n脑雾在这一阶段很常见——注意力需要费力维持，反应时间变慢，短期记忆也可能显得不可靠。这些对思维和记忆的影响会随着戒断而改善：一项对114名氯胺酮使用者的纵向研究发现，在停用氯胺酮12周后，言语记忆、视觉记忆、处理速度以及计划、专注和决策能力都出现了显著进步。\n\n膀胱症状\n如果你患有氯胺酮引起的膀胱炎（尿急、尿频、疼痛或尿中带血），现在停止使用能给膀胱最好的愈合机会。疼痛可能诱使人们重新使用氯胺酮来“自我用药”——这是一个值得用适当的疼痛支持来打破的循环。';

  @override
  String get ketamineReferenceDay14 =>
      '停用氯胺酮两周\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review》，PubMed Central\n\n思维更清晰\n随着药物完全清除，与长期使用氯胺酮相关的精神模糊和思维断裂开始消散。记忆和注意力得到改善，情绪趋于稳定。\n\n膀胱恢复开始\n对于早期膀胱炎，该综述强调，仅仅停止使用氯胺酮就是逆转症状最重要的一步，而越早停用，在损伤变成永久性之前获得恢复的几率就越大。两周的戒断正是这一过程的开始。';

  @override
  String get ketamineReferenceDay30 =>
      '停用氯胺酮一个月\n\n来源：《Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users》，Winstock et al.，BJU International（2012）\n\n膀胱恢复\n治疗氯胺酮引起的膀胱炎最重要的一点就是停止使用氯胺酮。这项针对娱乐性氯胺酮使用者的研究发现，在有泌尿症状的人中，51%在停止使用后报告症状改善，而不到4%的人情况恶化。停用越早，结果越好。\n\n心智与情绪\n到一个月时，认知和情绪继续变得清晰。心理和社会支持能切实提高坚持停用的几率——在有支持的情况下，停用效果最好。';

  @override
  String get ketamineReferenceDay90 =>
      '停用氯胺酮三个月\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review》，PubMed Central\n\n持续恢复\n停用氯胺酮后的膀胱恢复往往是渐进的；该综述描述了停用后症状严重程度的改善，尽管这一过程可能漫长且因人而异。在那些会有所反应的病例中，三个月给了泌尿道持续的时间来愈合。\n\n心智\n与戒断早期相比，思维和情绪都明显更加清晰，渴求也更少。持续或严重的膀胱症状应由泌尿科医生进行评估。';

  @override
  String get ketamineReferenceDay180 =>
      '停用氯胺酮六个月\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review》，PubMed Central\n\n半年之后\n随着持续戒断，在对停用有反应的病例中，膀胱症状继续改善，思维、记忆和情绪保持稳定。使用冲动已经大大减弱。\n\n恢复信号\n已成形的膀胱损伤可能无法完全恢复，这正是尽早停用如此重要的原因。无论你在哪个阶段停用，坚持不碰都能给膀胱带来最好的结果。';

  @override
  String get ketamineReferenceDay365 =>
      '停用氯胺酮一年\n\n来源：《Ketamine-Induced Cystitis: A Comprehensive Review》，PubMed Central\n\n一年之后\n十二个月的戒断，让早期发现的病例中的膀胱获得了最充分的恢复机会，也让思维、记忆和情绪保持稳定和清晰。让停用变得困难的心理依赖已基本消退。\n\n更大的图景\n一年不碰是一个意义深远的改变——体现在身体健康、清晰度和自我掌控上。保留那些把你带到这里来的支持，就能守护这一切。';

  @override
  String get kratomReferenceDay1 =>
      '卡痛叶戒断：第一天\n\n来源：Swogger et al.（2022），《Understanding Kratom Use: A Guide for Healthcare Providers》，Frontiers in Pharmacology\n\n为什么会出现戒断\n卡痛叶的活性化合物作用于与传统阿片类药物相同的阿片受体。长期使用后身体会适应，因此停用会产生类似阿片类药物的戒断。这份临床指南将依赖和戒断描述为长期使用卡痛叶的公认风险。\n\n关于发作时间的证据\n指南中引用的动物研究显示，躯体戒断体征在大约12小时内出现，到24小时时焦虑样效应已经明显；人体确切的发作时间尚不明确，但常被报告的早期症状包括：\n• 坐立不安、焦虑和易怒\n• 肌肉酸痛和流鼻涕\n• 出汗和流泪\n• 渴求\n\n关于严重程度的说明\n该指南指出，使用时间越长、剂量越高，戒断就越严重、越持久。值得寻求受监督的医疗支持，尤其是在高剂量使用卡痛叶、或与阿片类药物同时使用时。';

  @override
  String get kratomReferenceDay3 =>
      '卡痛叶戒断：最艰难的几天\n\n来源：Singh et al.（2014），Drug and Alcohol Dependence——对马来西亚293名长期卡痛叶使用者的调查\n\n证据表明了什么\n这项调查并没有给出单一的“高峰日”，而是发现戒断的严重程度与使用量和使用时长相关：每天饮用三杯或更多卡痛叶的人，出现严重依赖和更困难戒断的几率显著更高。对大多数人来说，停用后的最初几天最艰难。\n\n常被报告的症状\n• 肌肉和关节酸痛、不宁腿\n• 尽管疲惫却失眠\n• 恶心、胃痉挛和腹泻\n• 焦虑、情绪低落和易怒\n• 强烈的渴求\n\n如何熬过去\n补水、休息和对症支持都有帮助。如果到目前为止戒断感觉严重，这与较大量或较长期的使用相符，而并非有什么异常——而且它往往会从这里开始缓解。';

  @override
  String get kratomReferenceDay7 =>
      '停用卡痛叶一周\n\n来源：Swogger et al.（2022），《Understanding Kratom Use: A Guide for Healthcare Providers》，Frontiers in Pharmacology\n\n已过急性期\n指南中引用的人类自述数据显示，对大多数停用者来说，戒断症状会在大约一到三天内消退。到一周时，对大多数人而言，急性身体症状——肌肉酸痛、出汗、恶心——通常已经平息。可能残留的更多是心理层面：随着被卡痛叶刺激的阿片受体重新适应身体自身的信号，会出现疲劳、睡眠紊乱和情绪低落。\n\n一个真实的风险\n指南还指出，少数人发现卡痛叶非常难以戒除，在较大量、较长期使用者中报告的戒断更为严重且持续时间更长。这一周是常见的复吸时点，而且耐受性下降得很快——此时恢复以前的剂量（尤其是涉及阿片类药物时）确实很危险。';

  @override
  String get kratomReferenceDay14 =>
      '停用卡痛叶两周\n\n来源：美国国家药物滥用研究所（NIDA），《Kratom》\n\n超出已研究的时间窗口\n关于卡痛叶戒断时间的受控人体数据通常只覆盖最初几天，因此并没有确切的研究来锚定某个具体的“两周”里程碑。已有记载的是更宏观的模式：卡痛叶作用于与传统阿片类药物相同的阿片受体，随着长期使用停止，这些受体会逐渐恢复对身体自身信号的敏感性。\n\n人们通常报告什么\n• 食欲和精力往往得到改善\n• 睡眠趋于更可靠\n• 情绪通常更稳定，尽管仍有波动\n\n渴求仍会被压力和熟悉的线索触发，因此为它们准备好应对计划仍然有用。';

  @override
  String get kratomReferenceDay30 =>
      '停用卡痛叶一个月\n\n来源：美国国家药物滥用研究所（NIDA），《Kratom》\n\n正在恢复的奖赏系统\nNIDA将卡痛叶描述为作用于大脑的阿片受体，并将依赖和戒断列为长期使用的公认风险。没有具体研究锚定“一个月”的恢复里程碑，但基于阿片受体的依赖的一般规律是，随着持续戒断，大脑对日常愉悦的反应会逐渐正常化。\n\n停用一个月能建立起什么\n一个月不碰卡痛叶，就是一个月的规律睡眠、饮食和作息，取代了过去使用所需的时间和精力。渴求往往出现得更少、感觉更可控，尽管高压力时刻仍然是最脆弱的时刻。';

  @override
  String get kratomReferenceDay90 =>
      '停用卡痛叶三个月\n\n来源：美国国家药物滥用研究所（NIDA），《Kratom》\n\n更平稳的日常状态\n卡痛叶作用于阿片受体，因此三个月不碰它，让大脑的奖赏和应激系统有了持续的时间来安定。许多人报告，离活跃使用越远，思维就越清晰、动力就越稳定。\n\n为什么这很重要\n使用离现在越久，卡痛叶日常的牵引力就越趋于消退——这使得这一里程碑成为持久恢复的坚实基础。';

  @override
  String get kratomReferenceDay365 =>
      '停用卡痛叶一年\n\n来源：美国国家药物滥用研究所（NIDA），《Kratom》\n\n早已越过急性戒断\nNIDA并没有公布具体的卡痛叶一年恢复时间线，但一年的持续戒断早已超出卡痛叶研究中记载的急性期和早期心理戒断窗口。对大多数走到这一步的人来说，渴求很少出现，也远更容易应对。\n\n更大的图景\n一年的戒断代表着健康、财务状况和自我掌控上的实质性改变。保持与支持系统的联系，有助于守护这份进展。';

  @override
  String get maoiReferenceDay3 =>
      'MAOI停药：风险最高的阶段\n\n来源：Dilsaver（1988），关于MAOI停药反应的研究\n\n重要安全警告\n在所有抗抑郁药类别中，MAOI的停药风险最为严重。突然停药——尤其是苯乙肼和反苯环丙胺——可能引起严重反应，包括：\n• 严重的焦虑和激越\n• 言语急迫和坐立不安\n• 失眠或嗜睡\n• 幻觉\n• 谵妄和偏执性精神病\n\n如果你正在出现这些症状，请立即就医。\n\nMAOI如何起作用\nMAOI通过不可逆地与单胺氧化酶（MAO-A和MAO-B）结合并使其失活来发挥作用。这些酶通常负责分解大脑和肠道中的血清素、去甲肾上腺素、多巴胺和酪胺。由于被摧毁的是酶本身而不只是被阻断，恢复取决于身体产生新的酶，而不是药物从血液中清除的速度。';

  @override
  String get maoiReferenceDay7 =>
      '停用MAOI一周：MAO酶合成正在进行中\n\n来源：《Monoamine Oxidase Inhibitors (MAOIs)》（StatPearls，NCBI Bookshelf）\n\n酶的恢复过程\n与可逆性地抑制脑化学物质再摄取的SSRI、SNRI和TCA不同，不可逆的MAOI（苯乙肼、反苯环丙胺）会永久性地摧毁单胺氧化酶分子。因此，临床上的清除期取决于身体合成全新酶的速度——大约2周——而不是药物本身从血液中清除的速度。\n\n一周时发生了什么\n• MAO-A和MAO-B酶的合成正在顺利进行，大约处于约2周再合成窗口的中途\n• 第3天所描述的高风险期正在过去，不过密切的医疗监督仍然重要\n\n饮食注意事项\nMAOI治疗需要低酪胺饮食，因为这些酶通常会分解酪胺，防止其诱发高血压危象。指南建议在这一再合成窗口期内继续遵守饮食限制——何时可以安全放宽，应由你的开药医生告知。';

  @override
  String get maoiReferenceDay14 =>
      '停用MAOI两周：MAO酶活性大幅恢复\n\n来源：Fritz et al.（1983），Biological Psychiatry\n\n关键的两周节点\n两周是停用不可逆MAOI（如反苯环丙胺或苯乙肼）后MAO酶恢复的标准临床清除期。这项针对反苯环丙胺的研究发现，血小板MAO-B的催化活性——在给药后一天内急剧下降——在大约两周内反弹至正常，因为身体用携带活性酶的新血小板替换了受药物影响的血小板，尽管总MAO-B蛋白水平从未改变。\n\nMAO酶的恢复\n• 此时血小板MAO-B活性已大幅恢复\n• 遵循大致相似再合成时间线的大脑MAO-A和MAO-B也大多得到恢复\n• 正常的酪胺代谢正在重新建立——在与你的开药医生商量后，MAOI的饮食限制通常可以放宽\n\n大脑化学平衡回归\n随着MAO酶活性恢复，受MAOI影响的大脑化学系统开始回归自然调节：\n• 血清素、去甲肾上腺素和多巴胺不再因MAO抑制而升高\n• 单胺受体的超敏性（由长期被MAOI升高的大脑化学物质水平引起）开始消退\n• 自然的情绪和精力调节正在回归';

  @override
  String get maoiReferenceDay30 =>
      '停用MAOI一个月：大脑化学系统重新平衡\n\n来源：《Monoamine Oxidase Inhibitors (MAOIs)》（StatPearls，NCBI Bookshelf）\n\n一个月的评估\n停用MAOI一个月，已经远远过了本来源所述约2周的MAO酶再合成窗口，因此此时MAO酶活性已完全恢复，大脑化学系统处于完全自然的调节之下。\n\n到一个月时已经恢复的\n• MAO酶活性完全恢复：MAO-A和MAO-B都完全正常运作\n• 饮食限制解除：无需酪胺限制的正常饮食\n• 血清素自然降解：大脑正常的血清素周转循环已恢复\n• 儿茶酚胺自然调节：多巴胺和去甲肾上腺素水平由自然的MAO活性调节\n\n药物相互作用注意事项\nMAOI与血清素类药物存在危及生命的相互作用。这些相互作用风险在一个月节点时已解除。不过，在开任何新药时，都要告知你的开药医生和药剂师你曾使用过MAOI。';

  @override
  String get maoiReferenceDay90 =>
      '停用MAOI三个月：早已度过戒断\n\n来源：《Antidepressant Withdrawal Syndrome》，Therapeutics Letter 112（2018），Therapeutics Initiative，见NCBI Bookshelf\n\n各类抗抑郁药的戒断\n这篇证据综述将抗抑郁药戒断视为一种真实的耐受与依赖现象——把抗抑郁药“与阿片类药物和苯二氮卓类药物并列”。其详细证据集中于SSRI和SNRI，但戒断反应在各类抗抑郁药中都被认可，包括停用MAOI后。症状“通常在停药后几天内出现”，“大多数……在2周内消退”，不过有些持续时间更长。\n\n三个月处于什么位置\n到三个月时，急性戒断阶段对绝大多数人来说早已过去，身体也早已重新适应了在没有MAO抑制的情况下调节单胺类物质。\n\n关于“受体重新敏感化”的恢复信号\n自信地声称血清素、去甲肾上腺素和多巴胺受体都已在三个月时“重新敏感化”，超出了证据所能确定的范围。可以确信的是：此时戒断阶段通常已经消退，对大多数人来说，情绪、精力和情绪范围正在自然的、自我调节的大脑信号传导上趋于稳定。\n\n戒断与复发\n该Letter强调要把戒断与基础疾病的真正复发区分开来。如果症状在三个月时持续存在，应与你的开药医生一起评估，而不是想当然地认为它们只是戒断。';

  @override
  String get maoiReferenceDay180 =>
      '停用MAOI六个月：长期恢复\n\n来源：Zwiebel & Viguera（2022），Cleveland Clinic Journal of Medicine\n\n六个月的评估\n这篇综述解释，抗抑郁药的部分作用方式是使单胺受体随时间下调，而这种下调在停药后需要数周到数月才能逆转——这一过程比大约两周的MAO酶再合成本身更慢。\n\n六个月处于什么位置\n对绝大多数人来说，六个月已经从容地超过了那个数周到数月的受体重新调整窗口，同时酶活性也在第一个月内就完全正常化了。恢复信号：文献中并没有以逐日确定的方式确立血清素、去甲肾上腺素和多巴胺受体完全重新敏感化的精确时间线——可以确信的是，到六个月时，大多数人正在自然的、自我调节的大脑信号传导上运作。\n\n关于苯乙胺的说明\nMAOI还会抑制苯乙胺（PEA）的降解，这是一种与情绪和精力相关的痕量胺。预计其代谢会随着MAO酶的总体恢复而正常化，不过——与受体重新敏感化一样——研究文献中并没有确立针对PEA的具体时间线。';

  @override
  String get maoiReferenceDay365 =>
      '停用MAOI一年：恢复达成\n\n来源：《Monoamine Oxidase Inhibitors (MAOIs)》（StatPearls，NCBI Bookshelf）\n\n一年：一项了不起的成就\n完成停用MAOI一周年，是一个真正重要的里程碑。MAOI是最难停用的抗抑郁药之一，其不可逆的作用机制、严格的低酪胺饮食以及不同于任何其他抗抑郁药类别的药物相互作用注意事项，都使停用过程格外艰难。\n\n这一年意味着什么\n• 整整一年自然的、自我调节的单胺氧化酶活性，建立在一个月内就已完成的酶再合成之上\n• 证明了在没有药物驱动的MAO抑制下维持健康状态的能力\n• 一段足够长的记录，足以确信第3天的急性停药风险已经牢牢留在身后\n\n关于MAOI的说明\n对于某些难治性疾病和非典型抑郁症，MAOI仍然具有独特的疗效。成功停药并不会削弱它们作为药物的价值——它证明了大脑的恢复能力，以及患者驾驭一个格外艰难的医疗过程的能力。一个持久的注意事项：继续告知任何新的开药医生或麻醉师你曾使用过MAOI，因为有些药物相互作用风险值得无限期地标明。';

  @override
  String get marijuanaReferenceDay1 =>
      '大麻戒断：第一天\n\n来源：《The cannabis withdrawal syndrome: current insights》，Substance Abuse and Rehabilitation（2017），见PubMed Central\n\n大麻戒断是真实存在的\n这篇同行评审综述确认，大麻戒断综合征（CWS）是一种经过充分验证的临床状况，大约90%被诊断为依赖大麻的人停用后都会出现。其平均峰值严重程度与烟草戒断综合征相当。\n\n为什么会出现戒断\nTHC作用于内源性大麻素系统——参与情绪、食欲、睡眠、记忆和压力的CB1受体。长期使用时大脑会下调这一系统；当大麻停止后，它暂时处于低活跃状态。该综述指出，CB1受体在戒断约四周内恢复正常功能。\n\n第一天的发作\n该综述记载，身体症状往往最先出现——在最后一次使用后的1–3天内——而心理症状则在2–10天内出现。早期症状包括：\n• 易怒、焦虑和坐立不安\n• 入睡困难\n• 食欲下降\n• 身体紧张、出汗或发冷\n• 情绪低落\n\n严重程度\n大麻戒断综合征在医学上并不危险，症状通常为轻度到中度，但该综述指出，这些症状可能令人苦恼到足以诱发复吸——这正是理解时间线如此重要的原因。';

  @override
  String get marijuanaReferenceDay3 =>
      '大麻戒断时间线：最初的几天\n\n来源：《Time-course of the DSM-5 cannabis withdrawal symptoms in poly-substance abusers》，BMC Psychiatry（2013），见PubMed Central\n\n一条被测量的时间线\n这项研究对90名患者追踪了四周的DSM-5大麻戒断症状，描绘出了症状如何上升和下降的最清晰图景之一。总体严重程度遵循一条曲线：先上升，随后在接下来的几周里下降。\n\n哪些症状较早达到高峰\n几种最具身体破坏性的症状在停药后的最初几天达到高峰：\n• 失眠——大约在第1天达到高峰\n• 紧张不安——大约在第4天达到高峰\n• 情绪低落和身体症状——大约在第5天达到高峰\n• 坐立不安——大约在第6天达到高峰\n\n哪些症状较晚达到高峰\n该研究发现，有些症状出现并达到高峰的时间晚于第一周：\n• 生动而不愉快的梦境——大约在第11天达到高峰\n• 易怒和愤怒——大约在第14天达到高峰\n\n睡眠与大麻\n延迟出现的生动梦境反映了REM反弹：大麻在使用期间抑制REM睡眠，一旦停止，大脑就会过度补偿。作者认为这一症状足够普遍，应被列入正式的戒断标准之中。\n\n对第三天而言的要点\n到第三天，你正处于早期身体症状高峰的最深处——失眠、紧张不安和坐立不安接近最严重的程度。这条一致且可预测的曲线本身就是一种安抚：这些症状有已知的走向，它们会从这里开始消退。';

  @override
  String get marijuanaReferenceDay7 =>
      '停用大麻一周：熬过了最糟的阶段\n\n来源：《The cannabis withdrawal syndrome: current insights》，Substance Abuse and Rehabilitation（2017），见PubMed Central\n\n一周在这个综合征中处于什么位置\n这篇综述记载，大麻戒断综合征通常持续约三周，最令人苦恼的时期落在第一周到第三周之间。到一周时，最早的身体症状——失眠、食欲不振、坐立不安——通常已经过了高峰，正在缓解。\n\n哪些仍在平复\n该综述区分了较早达到高峰的身体症状和较晚达到高峰的心理症状。到一周时：\n• 身体不适和食欲大体上正在改善\n• 对许多人来说睡眠仍然紊乱，生动的梦境（REM反弹）往往在此时前后达到高峰\n• 易怒和情绪可能仍然偏高，因为它们往往在前两周内较晚达到高峰\n\n恢复的神经生物学\n在这些变化背后，该综述指出，被下调的CB1受体在戒断约四周内趋于恢复正常功能。戒断一周时，这种重新调节已经顺利进行——即便有些症状仍在持续，系统也正在恢复。\n\n要点\n达到一周意味着急性身体症状高峰已经过去。剩下的睡眠和情绪症状属于一个已知、有限进程的综合征的一部分，它会在接下来的几周里继续消退。';

  @override
  String get marijuanaReferenceDay14 =>
      '停用大麻两周：急性戒断结束\n\n来源：Budney, AJ et al.（2003）——关于大麻戒断时间进程的同行评审研究\n\n研究发现\n这项同行评审研究系统地记录了经常使用者大麻戒断症状的时间进程。结果显示，急性戒断综合征在第一周内达到高峰，并且对大多数症状来说，在停用后2周内大体上消退。\n\n到2周时消退的\n该研究记载，到第14天时，研究参与者身上的以下症状已大体消退：\n• 身体不适和身体症状\n• 食欲紊乱\n• 大多数睡眠紊乱\n• 峰值期的易怒和焦虑\n\n可能持续超过2周的\n该研究还识别出在一些使用者身上持续超过两周节点的症状：\n• 情绪低落\n• 注意力集中困难\n• 睡眠质量（尽管在改善）\n\n两周节点的意义\n度过两周节点之所以意义重大，是因为它意味着急性戒断综合征已大体完成。此后的挑战主要与更长期的大脑恢复以及管理大麻使用的根本原因有关，而非停止使用后的急性生理反应。';

  @override
  String get marijuanaReferenceDay30 =>
      '停用大麻一个月：记忆功能改善\n\n来源：Pope et al.（2001），Archives of General Psychiatry\n\n大麻与记忆：问题所在\n这项研究对大量、长期的大麻使用者进行了28天经确认的戒断随访，并将他们的思维和记忆测试结果与轻度使用者和非使用者进行了比较。在戒断开始时，以及第1天和第7天再次测试时，大量使用的人在单词表回忆上的表现差于对照组——这一缺陷与他们的尿中THC代谢物水平相关，反映的是近期药物暴露而非终身使用量。\n\n好消息：到第28天恢复\n到第28天时，大量使用的人、轻度使用者和非使用者在研究的思维和记忆测试中表现几乎相同。此时，终身大麻使用总量与测试表现之间也没有显著关系。\n\n这在30天时意味着什么\n• 言语学习和回忆已恢复到对照组水平\n• 第一周所见的残余缺陷已经消退\n• 早先剩余的缺陷与近期暴露有关，而非永久性损伤\n\n证据表明了\n到第28天，大量使用的人在研究的整套思维和记忆测试中几乎与轻度使用者和非使用者无法区分。第一周所见的言语学习和回忆缺陷已恢复到对照组水平。';

  @override
  String get marijuanaReferenceDay60 =>
      '停用大麻两个月：注意力更加敏锐\n\n来源：Roten et al.（2015），Addictive Behaviors\n\n研究问题\n这项针对青少年的大麻戒断研究，在大约两个月的时间里追踪了记忆和思维测试分数以及尿液检测结果，将仍在使用的使用者与最近停止或保持戒断的人进行了比较。\n\n主要发现\n持续的戒断与以下方面的显著改善相关：\n• 综合记忆分数\n• 言语记忆——受影响最严重的领域\n• 运动和反应速度表现\n\n两个月时\n到大约八周的持续戒断时，记忆以及运动和反应速度表现分数已经可测量地攀升到高于活跃使用期间的水平，与经确认的未使用状态密切相关，而不仅仅是时间的推移。\n\n研究表明了什么\n在患有大麻依赖的青少年和年轻成年人中，持续戒断在大约两个月的治疗窗口期内带来了综合记忆、言语记忆以及运动和反应速度表现的显著提升。';

  @override
  String get marijuanaReferenceDay90 =>
      '停用大麻三个月：情绪稳定性回归\n\n来源：Connor et al.（2022），Addiction——关于大麻戒断的临床综述\n\n戒断时间线实际是什么样的\n这篇综述描述大麻戒断症状通常在停用后24–48小时开始，并大约在第2–6天达到高峰。愤怒、攻击性和情绪低落可能早在第一周就出现，但通常在大约两周的戒断后达到高峰；尤其是睡眠紊乱，可能比其他症状持续更久。\n\n三个月处于什么位置\n到三个月时，你已经远远超出了有记载的戒断进程：症状通常在24–48小时内开始，大约在第2–6天达到高峰，即便是较慢的情绪和睡眠症状也在随后的几周内达到高峰。九十天让那些由戒断驱动的情绪和睡眠影响有了数月的时间来平复。\n\n关于内源性大麻素系统的说明\n大麻戒断研究还显示，被下调的CB1受体在戒断约四周内趋于恢复正常功能。到90天时，你已经远远超出了那个受体恢复窗口。\n\n展望\n该综述还讨论了脱毒后的预后和复吸预防，强调持续的支持和应对策略在急性戒断窗口期之后仍然重要。';

  @override
  String get marijuanaReferenceDay180 =>
      '停用大麻六个月：计划与决策能力恢复\n\n来源：Crean, Crane & Mason（2011），Journal of Addiction Medicine\n\n大麻之后的计划与决策能力\n这篇综述考察了从使用后最初几个小时到长期戒断期间的注意力、决策、自我控制、工作记忆和言语流畅性。到六个月时，你已经远远超出了短期影响，深入到了恢复期。\n\n研究发现\n与大量使用相关的若干问题会随着持续戒断而消退，一些研究发现到28天时即已恢复。在大量、早发型使用之后恢复最慢的领域包括：\n• 决策和冒险行为——被特别标记为在大量、长期使用者中缺陷可能长期持续的领域\n• 抽象推理和言语技能——尤其是在17岁之前开始使用的成年人中受损\n\n早发型的恢复\n六个月已经远远超出了这篇综述中的短期影响。计划、决策和推理能力会随着持续戒断继续改善，使持续戒断成为进一步恢复的最有力途径。\n\n更大的图景\n对于成年后开始、较轻度的使用，前景更为有利——许多人在六个月时报告思维更清晰、决策更稳定、自我导向感更强。最大的收获来自保持戒断，尤其是在大量或早发型使用之后。';

  @override
  String get marijuanaReferenceDay365 =>
      '停用大麻一年：大脑结构恢复\n\n来源：《Hippocampal harms, protection and recovery following regular cannabis use》，Translational Psychiatry（2016），见PubMed Central\n\n大麻引起的结构变化\n这项脑扫描研究考察了海马体——一个对记忆至关重要的大脑区域——在目前使用者、曾经使用者和非使用者中的情况。未接触过CBD的目前使用者，其海马体比对照组小约11%，脑细胞健康标志物低约15%。\n\n关键发现：戒断带来恢复\n曲线拟合分析支持一种“保护与恢复”模型。关键的是，曾经的使用者——平均戒断约29个月——在任何完整性指标上都与非使用对照组没有差异。作者得出结论：THC相关的记忆区域损伤“可以通过延长的戒断期得到恢复”。\n\n一年及以后的大脑恢复\n停用大麻一年时，大脑的记忆系统已经深入恢复之中：海马体大小和脑细胞健康正重新向正常水平靠拢，支持记忆和情绪控制。\n\n恢复信号\n戒断约29个月的曾经使用者在研究的海马体健康指标上与非使用者相当。到一年时，记忆系统已经沿着那条有记载的恢复路径向正常迈进。';

  @override
  String get mdmaReferenceDay1 =>
      'MDMA之后：低潮期\n\n来源：Meyer（2013），《3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives》，Substance Abuse and Rehabilitation\n\n为什么你会感到低落\nMDMA的作用方式是促使血清素大量释放（并伴随一些多巴胺）。之后大脑会暂时性地血清素耗竭。这篇综述描述了一种情绪下降——即所谓的“周中忧郁”——研究人员在初用者和有经验使用者身上都测量到，发生在使用后2到5天。\n\n哪些有帮助\n• 补水和营养食物\n• 睡眠\n• 耐心——这种低落是耗竭，而不是永久状态\n\n单次使用后的低潮期不同于与依赖相关的戒断，同一篇综述将后者描述为涉及渴求但没有显著的身体症状。';

  @override
  String get mdmaReferenceDay3 =>
      'MDMA之后的几天\n\n来源：Meyer（2013），《3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives》，Substance Abuse and Rehabilitation\n\n周中忧郁\n这大致就是这篇综述在讨论“周中忧郁”时所描述的时间窗口——在使用后2到5天测量到的情绪下降，在初用者和有经验使用者身上都存在，与短期的血清素耗竭有关，而非长期改变。\n\n哪些在改善\n• 情绪通常从此时前后开始从最低点回升\n• 精力恢复\n• 睡眠开始正常化';

  @override
  String get mdmaReferenceDay7 =>
      '停用MDMA一周\n\n来源：Meyer（2013），《3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives》，Substance Abuse and Rehabilitation\n\n已经过了周中忧郁\n对大多数人来说，一周已经过了这篇综述所关联急性低潮期的2到5天窗口，因此情绪应当已经恢复正常。该综述指出，对于大量或反复使用的人，渴求可能作为依赖模式的一部分持续存在，尽管它并未将此描述为涉及显著的身体戒断症状。\n\n何时寻求帮助\n如果低落的情绪、焦虑或睡眠问题在一周后仍持续，那可能就不只是低潮期了——值得与专业人士谈谈。';

  @override
  String get mdmaReferenceDay14 =>
      '停用MDMA两周\n\n来源：Meyer（2013），《3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives》，Substance Abuse and Rehabilitation\n\n恢复时间线\n对于单次使用的低潮期，两周已经远远过了这篇综述所记载的2到5天下降窗口，因此情绪、睡眠和注意力应当已经稳定。在大量或反复使用之后，恢复会持续到低潮期之后，而戒断期间的影像学研究显示血清素再循环能力会随着持续戒断而上升。\n\n这对你意味着什么\n如果你的使用是偶尔的，你可能已经熬过了最糟的阶段。如果是频繁或大量的，请对自己有耐心——血清素信号传导的完全恢复是一个比两周更长的过程，将在后续里程碑中介绍。';

  @override
  String get mdmaReferenceDay30 =>
      '停用MDMA一个月\n\n来源：《Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users》，见PubMed\n\n一个月处于什么位置\n急性低潮期和戒断早已过去，情绪、思维和记忆也更加稳定。影像学研究显示，MDMA会降低大脑处理血清素的能力，而这种能力会随着持续戒断而恢复。\n\n恢复信号\n同一项研究显示血清素再循环能力会随着持续戒断而恢复。情绪和血清素功能首先改善，而记忆则沿着它自己的恢复时间线继续——持续戒断对两者都有支持作用。';

  @override
  String get mdmaReferenceDay90 =>
      '停用MDMA三个月\n\n来源：《Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users》，见PubMed\n\n持续的恢复\n随着持续戒断，大脑的血清素系统继续恢复，尤其是在更深层的大脑区域。此时情绪和睡眠通常已经稳定。\n\n恢复信号\n持续戒断推动着血清素转运体在各个脑区持续恢复，同时情绪和睡眠保持稳定，思维和记忆的恢复也在继续。';

  @override
  String get mdmaReferenceDay365 =>
      '停用MDMA一年\n\n来源：《Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users》，见PubMed\n\n一年之后\n经过一年的戒断，大脑的血清素处理能力已经大幅恢复，情绪也很稳定。\n\n恢复信号\n整整一年的戒断为血清素系统提供了漫长的恢复窗口。影像学研究显示血清素再循环能力会随着戒断而上升，使血清素的大幅恢复成为这一阶段最清晰的生物学信号。';

  @override
  String get methReferenceDay1 =>
      '甲基苯丙胺戒断：最初24小时\n\n来源：McGregor et al.，《The nature, time course and severity of methamphetamine withdrawal》，Addiction（2005），见PubMed\n\n崩溃期\n甲基苯丙胺促使多巴胺大量释放；当使用停止时，系统被留在了耗竭状态。这项研究在戒断的最初三周里逐日追踪了戒断症状，发现总体严重程度在最后一次使用后的24小时内达到最高——即“崩溃”，一种从极度兴奋到身心俱疲的骤然转变。\n\n第一天的症状\n该研究记载了此刻最强烈的戒断特征：\n• 极度疲劳和睡眠增加（睡眠过多）\n• 食欲增加（甲基苯丙胺会强烈抑制食欲）\n• 情绪低落和失去快感\n• 强烈的渴求\n• 焦虑和易怒\n\n身体安全\n甲基苯丙胺戒断综合征本身通常不危及生命，但该研究测量到的与抑郁相关的症状在早期可能很严重，并可能包含自杀意念。强烈建议进行医疗监督，尤其是对大量使用的人。\n\n它开始缓解\n这项研究令人鼓舞的发现是：严重程度在一开始最高，然后下降。从这个24小时的高峰开始，症状在接下来的几天里稳步下降——最糟的时刻就是开始。';

  @override
  String get methReferenceDay3 =>
      '甲基苯丙胺戒断：第三天——仍处于急性期\n\n来源：McGregor et al.，《The nature, time course and severity of methamphetamine withdrawal》，Addiction（2005），见PubMed\n\n从高峰回落\n这项研究发现，总体戒断严重程度在最初24小时内达到高峰，随后在急性期（约7–10天）内以大致线性的模式下降。到第三天你已经过了最高点，但仍稳稳地处于急性期——即便趋势在向下，症状仍然显著。\n\n第三天的症状\n该研究追踪的、此刻仍然显著的特征：\n• 抑郁和失去快感\n• 强烈的渴求\n• 难以集中注意力和清晰地思考\n• 睡眠紊乱——失眠与睡眠过多交替\n• 持续的疲劳\n\n为什么会有这种感觉\n甲基苯丙胺戒断的强度反映了它所造成的多巴胺耗竭的规模。该研究测量到的与抑郁相关的症状在这些最初的几天最为明显——但重要的是，该研究发现总体戒断严重程度“在戒断第一周结束时降至接近对照水平”。\n\n这会过去的\n最难熬的一段是最初几天，数据表明从这里开始会稳步下降。把这种状态理解为暂时性的、属于大脑和神经的——而非永久性的状况——有助于熬过去。';

  @override
  String get methReferenceDay7 =>
      '停用甲基苯丙胺一周：急性期结束\n\n来源：McGregor et al.，《The nature, time course and severity of methamphetamine withdrawal》，Addiction（2005），见PubMed\n\n急性期结束\n这是研究中最令人鼓舞的发现之一。该研究报告，总体戒断严重程度——包括它所追踪的与抑郁相关的症状——“在戒断第一周结束时降至接近对照水平”，标志着急性期的结束。最陡峭的一段爬坡已经在你身后。\n\n戒断的两个阶段\n作者将甲基苯丙胺戒断描述为包含：\n• 一个持续约7–10天的急性期，期间症状严重程度从早期高峰稳步下降\n• 一个至少再持续两周的亚急性期，伴有较轻的、残留的症状\n\n第7天仍剩下什么\n进入亚急性期后，主要的挑战现在是心理层面的，而非急性崩溃：\n• 情绪低落，尽管比最初几天已大为改善\n• 渴求，尤其是在面对线索时\n• 注意力和记忆仍在恢复\n• 睡眠仍在平复\n\n身体恢复正在进行\n随着急性期结束，食欲已经恢复，精力也在慢慢积蓄，因为身体正在从甲基苯丙胺对睡眠、营养和心血管系统的影响中恢复。';

  @override
  String get methReferenceDay30 =>
      '停用甲基苯丙胺一个月：情绪安定，渴求仍在\n\n来源：Zorick et al.，《Withdrawal symptoms in abstinent methamphetamine-dependent subjects》，Addiction（2010），见PubMed Central\n\n追踪最初五周\n这项研究对保持戒断长达五周的甲基苯丙胺依赖者进行了随访，并将他们与健康对照者进行比较——给出了一个月节点所处位置的异常清晰的图景。\n\n到一个月时已经改善的\n• 抑郁症状“在戒断的最初2周内大幅下降到稳定的低水平”，到四周结束时已接近（尽管尚未在统计学上完全达到）健康对照水平（差距已缩小到一种临界、不显著的趋势）\n• 精神病性和精神病型症状到第二周结束时已达到较低的起始水平\n因此，到30天时，早期戒断中沉重的抑郁已大体缓解——这是一个真实、可测量的改善。\n\n仍在残留的\n该研究明确表明，有一种症状比其他症状持续更久：渴求“在戒断的整个5周内仍以降低的水平持续存在”。渴求比第一周弱，但并未消失，这正是为什么一个月仍是高风险期、持续支持很重要的原因。\n\n要点\n到一个月时，大脑的情绪机制已经恢复到足以让日常感受远好于早期戒断的程度——而持续存在的渴求是这个阶段的正常部分，而非失败的标志。';

  @override
  String get methReferenceDay90 =>
      '停用甲基苯丙胺三个月：愈合已经开始——要有耐心\n\n来源：Volkow et al.，《Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence》，Journal of Neuroscience（2001）\n\n关于这项研究\n这项具有里程碑意义的脑扫描研究对甲基苯丙胺使用者进行了两次随访——大约停用三个月和大约14个月——以观察多巴胺系统如何恢复。\n\n三个月处于什么位置\n到三个月时，早期戒断期早已结束，更深层的多巴胺恢复正在进行。同一项研究后来发现，在大脑奖赏和运动区域回收多巴胺的蛋白质，在停用甲基苯丙胺12–17个月后上升了约16%到19%。\n\n这对你意味着什么\n到90天时，急性戒断早已在你身后，情绪和睡眠已经改善，参与治疗的成效也高得多。但更深层的多巴胺恢复是一个更漫长的工程，会在接下来的一年里逐步展开。如果三个月时动力和快感仍然显得迟钝，这是预期中的，而不是失败的标志——这项研究中的轨迹从这里开始明显向上。\n\n为什么值得等待\n同一项研究表明，保持戒断才是推动恢复的原因：戒断时间越长，测得的DAT恢复就越大。三个月是基础；收获还会继续到来。';

  @override
  String get methReferenceDay180 =>
      '停用甲基苯丙胺六个月：心脏可以恢复\n\n来源：《Stopping Drug Abuse Can Reverse Related Heart Damage》，American College of Cardiology（2017），报道了JACC: Heart Failure上的一项研究\n\n甲基苯丙胺与心脏\n甲基苯丙胺是心脏毒性最强的娱乐性药物之一。它可能引起严重的高血压和心律失常，并随着时间推移导致甲基苯丙胺相关心肌病——一种导致心力衰竭的心肌变弱。\n\n研究发现\nACC报道了患有甲基苯丙胺相关心肌病的患者（全部都有显著下降的心脏泵血功能）。核心的、充满希望的发现是：戒除“可以逆转药物对心脏造成的损害，并改善心脏功能”。停止使用的患者比继续使用的患者预后好得多，作者强调，及早发现“可以防止心肌病进一步恶化”。\n\n为什么六个月很重要\n每一个戒断的月份，都移除了对你心脏持续的有毒压力，并给了心肌一个恢复的机会。到六个月时，你已经给了你的心血管系统一段实质性、持续的免受这种伤害的休息——这正是这项研究观察到改善的条件。\n\n恢复信号\n有证据支持的结果很有力：停止使用甲基苯丙胺可以逆转甲基苯丙胺相关的心脏损伤并改善心脏功能。六个月没有反复的兴奋剂伤害，给了心脏一个实质性的恢复窗口。';

  @override
  String get methReferenceDay365 =>
      '停用甲基苯丙胺一年：可测量的大脑恢复\n\n来源：Wang et al.，《Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence》，American Journal of Psychiatry（2004），见PubMed\n\n影像显示了什么\n这项脑扫描研究在戒断早期以及12–17个月后再次对甲基苯丙胺使用者进行了检查。它发现了真实的大脑恢复，其中一些区域比其他区域恢复得更快。\n\n好消息：深层大脑和思维的恢复\n丘脑，一个深层的大脑中继中心，随着长期戒断开始更正常地使用能量。这种恢复与更好的运动和言语记忆表现相伴随，因此脑扫描上的改善体现在了真实的思维和记忆中。\n\n奖赏回路恢复得更慢\n在12–17个月时，深层大脑中继中心已经强劲恢复，这种收获与更好的运动和言语记忆相伴随。奖赏和动力系统也在继续增强，使得一年的图景成为思维和记忆方面的一次重大恢复。\n\n这在一年时意味着什么\n到一年时，可以期待一个思维和记忆都远好于恢复早期的大脑——清晰、可测量的愈合。但如果动力或感受快感的能力有时仍然滞后，这与科学相符，而非个人的失败：这项研究发现那些奖赏回路可能恢复得更慢，有些缺陷在超过一年后仍存在。';

  @override
  String get methReferenceDay420 =>
      '停用甲基苯丙胺14个月：多巴胺标志物反弹\n\n来源：Volkow et al.，《Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence》，Journal of Neuroscience（2001）\n\n头条发现\n这项具有里程碑意义的脑扫描研究在戒断早期以及大约12–17个月后再次对甲基苯丙胺使用者进行了检查。在大脑奖赏和运动区域回收多巴胺的蛋白质上升了约16%到19%，并达到了与健康对照不再有显著差异的水平。戒断时间越长，恢复越大。\n\n为什么DAT很重要\n这些蛋白质在多巴胺释放后将其回收。甲基苯丙胺会耗竭它们，使多巴胺系统调节不良。它们在约14个月时反弹，是愈合的一个真实、可测量的迹象。\n\n恢复信号\n在12–17个月后，奖赏和运动区域中回收多巴胺的蛋白质上升了约16%到19%，并达到了健康对照水平。多巴胺系统已可测量地向正常反弹，而思维、记忆和运动也在继续改善。\n\n这在14个月时意味着什么\n多巴胺系统的“硬件”正在可测量地向正常恢复——这是乐观的真正理由。但完全的功能恢复（记忆、动力、精细运动控制）可能滞后于影像，并会随着持续的戒断继续改善。';

  @override
  String get methReferenceDay730 =>
      '停用甲基苯丙胺两年：思维和情绪持续改善\n\n来源：Iudicello et al.，《Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence》，Journal of Clinical and Experimental Neuropsychology（2010），见PubMed Central\n\n持续超过一年的恢复\n这项研究对甲基苯丙胺使用者进行了约13个月的随访，并将稳定戒断者与持续使用者和健康对照者进行了比较。稳定的戒断改善了整体思维并减少了情绪困扰，收获持续到一年以上。\n\n哪些在改善\n• 戒断者的整体思维追上了健康对照者，而持续使用者仍显著受损\n• 最大的收获在于处理速度和运动能力，尤其是对那些一开始受损最严重的人\n• 情绪明显改善：只有戒断者在抑郁和整体情绪上显示出显著改善\n\n恢复信号\n稳定戒断者在整体思维上追上了健康对照者，并报告了更少的情绪困扰。言语学习、工作记忆、计划和专注力可以持续改善到第一年之后，因此恢复趋势会延续到第二年。\n\n两年之时\n有证据支持的信息是：持续戒断在远超第一年之后仍然持续带来回报——思维更敏锐、情绪更好、功能稳步改善——即便有少数领域需要更长时间才能恢复。';

  @override
  String get nitrousOxideReferenceDay1 =>
      '第一天：气体已经离开，但要留意B12\n\n来源：Knuf & Maani，《Nitrous Oxide》，StatPearls（NCBI Bookshelf）\n\n它清除得有多快\n笑气起效迅速——2到5分钟——并且一旦你停止吸入，它同样迅速地从体内清除。到今天，气体本身已不在你的系统中残留。\n\n真正的风险不是气体\n停止后重要的是反复暴露可能已经造成的影响。笑气会使蛋氨酸合酶失活，这是一种依赖维生素B12的酶。StatPearls指出，反复暴露——无论是职业性的还是娱乐性的——都可能导致巨幼细胞性贫血以及大脑和神经功能障碍，在罕见情况下还会导致脊髓变性。\n\n如果你曾大量或经常使用\n笑气并未被记载会像阿片类药物或酒精那样引起身体戒断综合征，因此第一天并非你的身体在渴求这种药物。它关乎的是开始留意与B12相关的症状——将在接下来几个里程碑中介绍——并在任何症状出现时去做检查。';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72小时：没有身体戒断，但要留意神经症状\n\n来源：Knuf & Maani，StatPearls；Tikaria et al.（2026），Cureus\n\n与阿片类药物或酒精不同，笑气并未被记载会引起身体戒断综合征。这一阶段的冲动是习惯和渴求，而不是身体为了运转而在要求这种药物。\n\n留意以下症状\n一项对1,809例娱乐性笑气病例的系统综述（Tikaria et al.，2026）发现，大脑和神经症状——尤其是刺痛或麻木（感觉异常）——是与B12相关的损伤最常见的迹象，即便在标准血液检测看起来正常时也常常出现。步态问题和无力也有报告。\n\n如果你注意到其中任何一种\n请寻求医疗评估。同一篇综述发现，标准血液检测（血红蛋白、血清B12）会漏掉相当一部分受影响的患者——甲基丙二酸（MMA）和同型半胱氨酸检测更为敏感，如果你告知医生你使用笑气，应专门要求做这些检测。';

  @override
  String get nitrousOxideReferenceDay7 =>
      '一周：如果你曾大量使用，去做检测\n\n来源：Tikaria et al.（2026），《The Toxic Legacy of Recreational Nitrous Oxide Use》，Cureus\n\n证据表明了\n这篇系统综述发现，笑气引起的维生素B12缺乏往往是“功能性”的——大约一半受影响患者的血清B12看起来正常，即便他们确有真实的大脑和神经损伤。同型半胱氨酸和MMA异常的比例要高得多（分别占接受检测患者的84%和73%），是更可靠的标志物。\n\n该怎么做\n如果你的使用是大量或频繁的，停用一周是一个合理的时点去看医生，并专门要求做同型半胱氨酸和MMA检测——而不只是标准B12水平——尤其是如果你有任何刺痛、麻木、平衡问题或不明原因的无力。\n\n停止使用笑气并接受维生素B12治疗后，大脑恢复很常见：大型临床系列报告大多数随访患者获得部分或完全改善，恢复在治疗后的最初几个月里持续进行。';

  @override
  String get nitrousOxideReferenceDay14 =>
      '两周：大脑和神经症状值得随访\n\n来源：Tikaria et al.（2026），Cureus；Knuf & Maani，StatPearls\n\n有报道的情况\nTikaria et al.综述的病例报告和病例系列描述了与笑气相关的神经损伤，表现为感觉丧失、步态共济失调，有时还有影响行走的无力——这些表现可能类似于其他大脑和神经疾病，如果不向临床医生提及笑气使用，有时会被漏诊。\n\n关于时间线的恢复信号\n两个来源都没有报告一旦停止使用并治疗任何缺乏症后，恢复通常需要多长时间。病例报告描述了从完全恢复到持久缺陷的广泛结局——这在很大程度上取决于诊断前发生了多少损伤。整个文献一致的一点是：治疗越早，结局越好。\n\n如果你还没有做检查\n停用两周仍然是一个很好的时机去做血液检测，即便没有症状——尤其是同型半胱氨酸和MMA，而不仅仅是血清B12。';

  @override
  String get nitrousOxideReferenceDay30 =>
      '一个月：是习惯和渴求，而非身体依赖\n\n来源：Knuf & Maani，《Nitrous Oxide》，StatPearls（NCBI Bookshelf）\n\n你所处的位置\nStatPearls并未将笑气描述为会产生身体依赖综合征，因此停用一个月意味着任何残留的冲动都与习惯、社交场合或无聊有关，而非身体仍在适应药物的缺席。\n\nB12的问题\n如果你已经检测并治疗了B12缺乏，一个月是让你的医生检查你的水平——以及任何症状——是否有反应的合理时点。如果你没有检测过并且曾大量使用，仍然值得提出要求。\n\n受到保护的是什么\n每一个你不使用的月份，都是一个你没有在给任何现有的蛋氨酸合酶失活或随之而来的大脑和神经风险添砖加瓦的月份。';

  @override
  String get nitrousOxideReferenceDay90 =>
      '三个月：如果你还没复查，是时候了\n\n来源：Tikaria et al.（2026），《The Toxic Legacy of Recreational Nitrous Oxide Use》，Cureus\n\n我们所知道的——和不知道的\n这一研究基础建立在病例报告和病例系列之上，而非对照恢复研究，因此没有可靠的已发表时间线来说明症状在三个月时具体如何消退。证据确实表明的是，结局差异很大——一些轻度、早期发现缺乏的患者完全恢复，而那些延迟诊断或神经损伤更严重的患者可能有持久的缺陷。\n\n可操作的部分\n如果你有过任何大脑和神经症状，并且还没有做过随访血液检测或专科评估，停用三个月是一个合理的时点去做这些。如果你已经接受治疗并在改善，这是与你的医生确认趋势在继续的合理时机。\n\n保持停用最重要\n该综述在一个方面保持一致：持续的暴露会继续使B12失活并增加风险。不使用是你手中最有利的单一因素。';

  @override
  String get nitrousOxideReferenceDay365 =>
      '一年：最好的保护是持续戒断\n\n来源：Knuf & Maani，StatPearls；Tikaria et al.（2026），Cureus\n\n证据实际上落在哪里\n两个来源都没有承诺一个具体的恢复时间线，这一点值得坦诚——关于笑气和B12缺乏的文献几乎完全建立在个体病例报告之上，而非长期随访研究。已被充分确立的是机制：笑气每次使用都会使维生素B12失活，而停止使用则完全移除了这种持续的伤害。\n\n如果你有过与缺乏相关的症状\n病例报告描述了广泛的结局，从完全恢复到持续的神经症状，这在很大程度上取决于发生了多少损伤以及治疗得有多早。如果你在一年后仍感到症状，那是继续与神经科医生合作的理由，而非什么都做不了的标志——神经恢复可以持续一段较长的时间。\n\n确定无疑的\n一年不碰笑气，就是一年没有进一步的蛋氨酸合酶失活。这是两个来源都支持的一个保证。';

  @override
  String get opioidReferenceDay1 =>
      '阿片类药物戒断：第一天\n\n来源：《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，世界卫生组织（2009），见NCBI Bookshelf\n\n⚠ 安全提示\n在其他方面健康的人身上，阿片类药物戒断很少致命，但它会引起严重的身体痛苦，并带有很高的复吸风险。戒断一段时间后的复吸尤其危险，因为耐受性会迅速下降——使用与戒断前相同的剂量可能导致致命的过量。强烈建议进行医疗监督和阿片受体激动剂治疗。\n\n戒断何时开始\nWHO的戒断时间表按阿片类药物类型确定时间：\n• 短效阿片类药物（海洛因、羟考酮）：在最后一次使用后8–24小时发作，持续4–10天\n• 长效阿片类药物（美沙酮）：发作时间12–48小时，持续10–20天\n\n第一天的症状\nWHO指南列出了阿片类药物戒断的早期特征：\n• 焦虑和激越\n• 肌肉痉挛和酸痛\n• 眼鼻流泪流涕\n• 打哈欠和出汗\n• 失眠，伴有冷热交替发作\n• 早期恶心\n\n为什么感觉如此难受\n阿片系统调节疼痛、压力、情绪健康和基本舒适感。长期使用阿片类药物会抑制身体自身的阿片物质（内啡肽）产生。当阿片类药物被移除时，身体被留在没有其正常舒适系统的状态——所经历的疼痛、焦虑和痛苦，反映了这种抑制的深度。WHO指南建议支持性护理，包括每天饮用2–3升水，每天监测3–4次。';

  @override
  String get opioidReferenceDay7 =>
      '停用阿片类药物一周：高峰症状正在下降\n\n来源：《Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings》，世界卫生组织（2009），见NCBI Bookshelf\n\n高峰与下降\nWHO时间表将短效阿片类药物戒断定为4–10天，症状在这一窗口期内早期积聚然后缓解。到第一周结束时：\n• 呕吐和腹泻已大体消退\n• 肌肉痉挛不再那么严重\n• 身体痛苦显著减轻\n\n第7天仍剩下什么\n虽然急性身体症状正在改善，但显著的挑战仍在持续：\n• 失眠——睡眠紊乱是最持久的阿片类药物戒断症状之一\n• 情绪低落和情感平淡\n• 疲劳和无力\n• 渴求\n• 焦虑\n\n急性期后的戒断\n在最初的戒断期之后，睡眠问题、情绪波动和一阵阵的渴求可能持续数周或数月。在这个更长的恢复阶段，持续的支持最为重要。\n\n阿片受体激动剂治疗\nWHO指南将美沙酮和丁丙诺啡描述为能减轻戒断严重程度并支持恢复的有效治疗。这些药物还能降低阿片类药物使用障碍的死亡率，许多成功长期恢复的人在恢复早期全程使用它们。';

  @override
  String get opioidReferenceDay14 =>
      '停用阿片类药物两周：睡眠模式开始改善\n\n来源：关于阿片类药物与睡眠的同行评审药理学研究\n\n阿片类药物与睡眠的关联\n这篇研究论文考察了阿片类药物使用与睡眠紊乱之间的双向关系。研究发现记载了阿片类药物通过多种机制严重扰乱正常的睡眠结构：\n• 抑制慢波（深度）睡眠\n• 扰乱REM睡眠\n• 引起睡眠呼吸障碍（中枢性睡眠呼吸暂停）\n• 扰乱昼夜节律调节\n\n一个恶性循环\n该研究强调了这一问题的双向性质：阿片类药物使用扰乱睡眠，而睡眠不佳又增加疼痛敏感性和渴求强度，推动进一步使用阿片类药物。打破阿片依赖也意味着打破这个睡眠紊乱的循环。\n\n两周时的睡眠\n到阿片类药物戒断第14天，睡眠开始正常化：\n• 中枢性睡眠呼吸暂停（如果存在）在数天内消退\n• 深度慢波睡眠开始恢复\n• REM睡眠回到正常比例\n• 入睡变得更加可靠\n\n对许多人来说，睡眠在两周时仍是一个重大挑战，但轨迹明显在改善。更好的睡眠直接改善情绪、减少渴求，并支持恢复所需的清晰思维。';

  @override
  String get opioidReferenceDay30 =>
      '停用阿片类药物一个月：思维和记忆开始恢复\n\n来源：梅奥诊所（Mayo Clinic）\n\n理解阿片类药物使用障碍\n梅奥诊所解释，阿片类药物附着在大脑和全身的受体上，产生镇痛、欣快和嗜睡。随着反复使用，大脑的反应越来越弱，并产生更少的自身阿片样化学物质。这就形成了身体依赖。\n\n一个月时的思维和记忆\n到30天时，思维和记忆已经出现了有意义的恢复。最严重的脑雾已经消散，大脑前部——负责计划和自我控制的部分——正在恢复：\n• 决策能力正在改善\n• 工作记忆正在恢复\n• 处理速度在提高\n• 注意力更加可靠\n\n内啡肽系统\n到一个月时，大脑自然的内啡肽系统正在积极恢复：它正在产生更多自身的阿片样化学物质，并再次更正常地做出反应。随着这种恢复持续，情感平淡和较低的疼痛耐受性也在继续改善。\n\n复吸预防\n梅奥诊所强调，停止使用阿片类药物一个月并不意味着复吸风险已经过去——它仍然偏高。耐受性已经显著下降，这意味着用以前的剂量复吸会带来严重的过量风险。';

  @override
  String get opioidReferenceDay60 =>
      '停用阿片类药物两个月：大脑的压力回路开始安定\n\n来源：《Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence》，Frontiers in Pharmacology（2023）\n\n负面情绪从何而来\n这篇综述描绘了长期使用阿片类药物如何改变大脑的压力和恐惧回路。在戒断期间，这些回路变得过度活跃，而奖赏回路中的多巴胺信号下降。这种组合有助于解释恢复早期的焦虑、情绪低落和渴求。\n\n为什么两个月带来缓解\n关键的是，该综述记载其中一些改变是可逆的。在动物模型中，伏隔核壳区的树突棘密度丧失被描述为“一种持久但可逆的减少”，在几周内回到接近用药前的水平。随着这些压力和奖赏回路重新调节，早期恢复中情绪动荡的机制基础得以缓解——这与许多人在大约两个月时报告的反应性降低、情绪更稳定相一致。\n\n恢复信号\n文献中记载的可逆的树突棘密度和压力回路改变显示了一个真实的生物学恢复过程：驱动依赖负面情绪状态的回路，在戒断期间向其用药前状态回归。';

  @override
  String get opioidReferenceDay90 =>
      '停用阿片类药物三个月：奖赏化学开始恢复\n\n来源：《Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies》，Drug and Alcohol Dependence（2022），见PubMed Central\n\n多巴胺与阿片类药物\n阿片类药物推动大脑奖赏系统中的多巴胺释放。长期使用使该系统耗竭：在一项脑扫描研究中，回收多巴胺的蛋白质在开始时比健康水平低约30%。这有助于解释阿片类药物使用障碍和恢复早期所见到的快感丧失。\n\n恢复是渐进的\n这篇综述汇集了对同一个人在戒断期间反复扫描的纵向研究。多巴胺转运体缺陷在6–12个月的戒断中恢复了约20%，而早期戒断中所见的一些额叶灰质和白质异常在大约一个月后已不再可检测。到三个月时，你正处于这条恢复曲线的早期：奖赏和额叶系统正在可测量地修复，但尚未完成。\n\n人们的体验\n随着这些回路恢复，许多人在大约90天时注意到：\n• 对活动、食物和人际关系更真实的享受\n• 与恢复早期相比减少的渴求\n• 更清晰的思维和更好的决策\n\n恢复信号\n纵向人体影像显示，多巴胺转运体的可利用性在6–12个月的戒断中上升，而额叶灰质和白质异常则早得多地开始正常化。到90天时，可测量的大脑恢复已经确立。';

  @override
  String get opioidReferenceDay180 =>
      '停用阿片类药物六个月：免疫系统开始恢复\n\n来源：《Effects of opioid tolerance and withdrawal on the immune system》，Journal of Neuroimmune Pharmacology（2006），见PubMed\n\n阿片类药物与免疫系统\n这篇综述显示，长期使用阿片类药物以多种方式削弱免疫系统：\n• 阿片类药物对免疫细胞（T细胞、NK细胞、巨噬细胞）的直接作用\n• 免疫信号化学物质被扰乱\n• 下丘脑-垂体-肾上腺（HPA）轴被扰乱\n• 对感染的易感性增加\n\n恢复信号\n长期使用阿片类药物会抑制免疫系统的多个部分。到停用阿片类药物六个月时，那种持续的抑制已经消失了半年，免疫功能正在积极地向正常重建。\n\n六个月意味着什么\n六个月不碰阿片类药物，给了免疫细胞、免疫信号和身体的压力系统持续的时间向正常恢复。\n\n为什么这仍然重要\n这对注射使用阿片类药物的人尤其相关，他们面临诸如HIV和丙型肝炎等额外的感染风险。移除阿片类药物、改善营养和保持戒断，给了免疫系统持续恢复所需的条件。';

  @override
  String get opioidReferenceDay365 =>
      '停用阿片类药物一年：大脑结构和化学正在恢复\n\n来源：《Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies》，Drug and Alcohol Dependence（2022），见PubMed Central\n\n人体影像显示了什么\n这篇综述汇集了对同一批阿片类药物使用障碍患者在戒断期间不止一次进行扫描的研究。发现一致地指向恢复：\n• 奖赏和运动区域回收多巴胺的蛋白质，在开始时比正常低约30%，在停用阿片类药物6–12个月中上升了约20%\n• 早期戒断中所见的额叶灰质异常在大约一个月的戒断后已不再可检测\n• 白质（额叶和扣带回）以及静息态额叶活动也在第一个月内开始重新正常化\n\n一年处于什么位置\n到十二个月时，你已经处于或超过了这些研究测量的最长时间窗口。多巴胺系统有了最多的时间来恢复，而支持自我控制和判断的额叶回路已经修复了数月——这是人们在一年时所描述的思维更清晰、渴求更弱、情绪更稳定的生物学对应物。\n\n恢复信号\n到一年时，人体影像信号强烈地指向恢复：多巴胺转运体的可利用性在6–12个月的窗口内上升，而额叶结构和功能异常也有了数月的时间来正常化。';

  @override
  String get opioidReferenceDay730 =>
      '停用阿片类药物两年：一个稳定的基础\n\n来源：《Treatment of Opioid Use Disorder》，美国疾病控制与预防中心（CDC）\n\n一种慢性疾病，管理得当\nCDC将阿片类药物使用障碍描述为“一种可能影响任何人的慢性疾病”——“一种医学状况，而非道德缺陷”。达到两年的持续恢复，意味着你已经在其最脆弱的时期之一成功管理了这一状况。\n\nCDC认为有效的做法\nCDC的指导以能长期保持恢复稳定的治疗为核心：\n• 阿片类药物使用障碍的药物——丁丙诺啡、美沙酮和纳曲酮——CDC称其尤其有效\n• 将药物与行为治疗和咨询相结合\n• 持续时间长短不一、因人而异的治疗\nCDC指出，这些药物有助于“使大脑化学正常化”并缓解渴求——在活跃成瘾中感觉被劫持的化学机制，再次与你并肩协作。\n\n保持安全\nCDC敦促恢复中的人向医生询问重新使用和过量的风险，并随身备好纳洛酮。戒断期间耐受性下降，因此这么久之后重新使用阿片类药物尤其危险——了解这一点是保护你所建立成果的一部分。\n\n两年之时\nCDC明确指出，恢复往往是一个长期过程，而非终点线。两年不是旅程的终点——它是一个稳定、健康的基础，也是你所用方法有效的有力证据。';

  @override
  String get pornographyReferenceDay1 =>
      '第一天：重新掌控\n\n来源：Kraus et al.，Compulsive sexual behaviour disorder in the ICD-11，World Psychiatry（2018）\n\n临床上重要的问题不是色情使用本身。强迫性行为障碍的定义是：当一种模式造成显著的痛苦或功能损害时，持续难以控制重复的性行为。有问题的色情使用可能是这个更广泛问题的一种表现形式。\n\n这使得第一天变得具体而非神秘：你已经打断了一种你判定为失控的行为。完成的一天并不能证明大脑和神经的重置，但它确实给了你关于冲动何时出现、什么情境触发它们、以及你可以转而做什么的第一次真实观察。\n\n如果你的使用并不令人痛苦、不造成损害、也不难以控制，那么临床上的CSBD框架可能并不适用于你。这些里程碑针对的是那些有意改变有问题或强迫性使用的人。';

  @override
  String get pornographyReferenceDay3 =>
      '第三天：了解冲动可能是什么样子\n\n来源：Lewczuk et al.，Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use，Journal of Behavioral Addictions（2022）\n\n在一项预先注册的、具有全国代表性的波兰样本中（1,541名成年人），更强的自报类戒断体验与更高的CSBD和有问题的色情使用严重程度相关。在有问题的色情使用参与者中，常被报告的体验包括难以停止的性念头、难以控制的欲望、性唤起增强、易怒、情绪变化和睡眠问题。\n\n坐立不安、闯入性的性念头、强烈的冲动和易怒，在问题使用更严重的人身上有记载。如果它们大约在第三天出现，就把它们当作真实的类戒断模式来对待，并管理触发因素。\n\n写下哪些冲动实际发生了、它们之前发生了什么、以及什么应对方式有帮助。当触发因素被命名，而不是被当作一个神秘的大脑事件时，恢复就更容易引导。';

  @override
  String get pornographyReferenceDay7 =>
      '一周：一项随机戒断研究发现了什么\n\n来源：Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users，Archives of Sexual Behavior（2023）\n\n研究人员将176名经常的色情使用者随机分配为尝试七天戒断或照常继续。在整个样本中，戒断并未带来渴求、负面情绪或戒断症状的显著总体增加。\n\n一项探索性分析确实发现，在问题使用得分高且研究前每天使用色情的人中，渴求有所增加。这一结果需要重复验证，但它是有用的：对于更严重的问题使用者来说，艰难的第一周可能是真实的，而这项试验并不支持一种普遍的色情戒断综合征。\n\n如果你已经熬过了一周，那么相比任何通用的互联网时间线，你现在对自己的模式有了更好的证据。';

  @override
  String get pornographyReferenceDay14 =>
      '两周：绘制真正重要的触发因素\n\n来源：Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review（2023）\n\n这篇综述综合了66项研究，发现有问题的色情使用与多种因素的混合有关，而非单一的多巴胺机制。反复被识别的心理和社会因素包括渴求、压力、回避、孤独、自尊、负面信念和应对方式。\n\n两周让你反复暴露于工作日、周末、无聊、压力、独处、设备和可能诱发旧行为的其他情境。利用这些数据。如果压力是触发因素，设计一种压力应对方式。如果孤独是触发因素，增加联系。如果容易接触到是触发因素，改变环境。\n\n证据支持针对问题使用的驱动因素下功夫；它并不要求假装每个人都遵循同样的生物倒计时。';

  @override
  String get pornographyReferenceDay30 =>
      '一个月：控制比简单的频率计数更重要\n\n来源：Bőthe et al.，Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?，Addictive Behaviors（2021）\n\n在一个包含14,581名成年人的社区样本中，有问题的色情使用与男性和女性的性功能问题都存在中等程度的正相关。色情使用频率本身与这些问题的相关性较弱且为负。\n\n这一区分很重要。证据并不支持告诉每个色情使用者，观看频率本身就会损害性功能。临床上更相关的目标是失控以及围绕该模式的问题。\n\n到一个月时，将现在的生活与开始时相比：沉迷程度、损失的时间、停止的能力、性功能、关系冲突和痛苦。这些变化比等待一个神话般的第30天大脑重置更重要。';

  @override
  String get pornographyReferenceDay90 =>
      '三个月：持久的改变是可能的\n\n来源：Crosby & Twohig，Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial，Behavior Therapy（2016）\n\n这项小型随机试验在28名成年男性中比较了一个12节的ACT项目与等待名单。治疗结束时，ACT组的色情观看下降得多得多，并且实质性的减少在三个月的随访时仍然保持。\n\n这项研究并不能证明90天的戒断本身会产生同样的结果，而且其样本很小、人口构成也很窄。它所展示的确实很重要：有问题的色情使用是可以改变的，结构化的技能可以产生持续到即时治疗期之后的变化。\n\n如果你的进展仍然主要靠咬牙硬撑，三个月是一个加强其周围系统的好时机：触发计划、在不行动的情况下接纳冲动、环境摩擦、问责，以及在需要时的治疗。';

  @override
  String get pornographyReferenceDay180 =>
      '六个月：长期症状控制可以保持\n\n来源：Hallberg et al.，A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men，Journal of Sexual Medicine（2019）\n\n在137名性行为失控的男性中，为期七周的团体CBT比等待名单带来了更大的性欲亢进症状和性强迫的减少，同时改善了精神健康。治疗收益在三个月和六个月的随访中都保持稳定。\n\n这项研究涵盖的是更广泛的性欲亢进障碍，而非仅仅色情戒断，因此不应被转述为每个人都在六个月时在生物学上恢复了。它确实支持一个更有力也更有用的陈述：强迫性性行为的持续改善可以在这段时长内保持稳定。\n\n因此，六个月是一个维持性的里程碑。保留那些让控制变得更容易的习惯，而不是把这一天当作拆解它们的许可。';

  @override
  String get pornographyReferenceDay365 =>
      '一年：持久行为改变的证据\n\n来源：One-year follow-up effects of an acceptance-based treatment for hypersexuality（2026）\n\n在一年的随访中，这项基于接纳的治疗研究的参与者并未回到他们治疗前的性欲亢进水平。作者将这些发现描述为持久、具有临床意义益处的初步证据，其中对渴求的感知控制是随时间被追踪的过程之一。\n\n这是治疗随访的证据，而非一年大脑重置的证据。有意义的说法无论如何都更好：临床上相关的控制可以持续一年，而不是在最初的干预一结束就消失。\n\n你自己维持改变的一年，也是一份庞大的个人数据集。将现在的控制、痛苦、功能、人际关系和时间使用与你开始的地方相比；这些才是临床上重要的结局。';

  @override
  String get pornographyReferenceDay1825 =>
      '五年：长期控制才是结局\n\n来源：Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review（2026）\n\n现代综述将CSBD和有问题的色情使用视为涉及控制、痛苦、功能、情境和个体差异的复杂问题。并不存在经过验证的五年大脑和神经重置阈值。\n\n但五年并不是一个空洞的里程碑。它是1,825天维持你所选择的行为方向。由于临床问题是伴有痛苦或损害的持续失控，因此数年间持续的控制和恢复的功能本身就是有意义的结局。\n\n到这个阶段，有用的问题不再是你大脑是否达到了某个虚构的重塑百分比。而是旧的模式是否仍然控制着你的选择，或扰乱你想要的生活。如果它不再如此，那就是一项实质性的长期成功。';

  @override
  String get smokingReferenceDay1 =>
      '第一天：益处现在就开始\n\n来源：NHS Better Health\n\n益处从几分钟内开始——而非几天。烟雾一停止，身体就开始正常化。\n\n今天会发生什么\n• 20分钟：脉搏开始恢复正常\n• 8小时：血液中的一氧化碳下降一半；氧气水平正在恢复\n• 48小时：一氧化碳已降至非吸烟者的水平\n\n一氧化碳与红细胞结合的能力比氧气更强，会把氧气从你的血液中挤走。每个器官所获得的氧气都比应有的少。这在两天内逆转。\n\n戒断从第一天开始\n• 渴求——每次通常持续3–5分钟\n• 易怒和难以集中注意力\n• 食欲增加\n\n这些都是暂时的、可以管理的。NHS Better Health项目提供免费支持，包括应用程序和药剂师建议。';

  @override
  String get smokingReferenceDay3 =>
      '第三天：戒断高峰\n\n来源：McLaughlin, Dani & De Biasi\n\n到72小时时，尼古丁已从你的身体中清除。大脑在你的吸烟岁月里建立了额外的尼古丁受体；现在它们得不到足够的刺激，从而引起戒断综合征。\n\n高峰症状\n• 渴求——此刻最为强烈\n• 易怒、沮丧、坐立不安\n• 难以集中注意力\n• 焦虑\n• 头痛\n• 食欲增加\n• 咳嗽（气道正在清理——这是个好迹象）\n\n这是最难的一天。不会比这更糟了——从这里开始，随着你的大脑重新调整，症状会稳步缓解。\n\n尼古丁替代疗法（NRT）、伐尼克兰和安非他酮都能在这一阶段显著减轻戒断严重程度。';

  @override
  String get smokingReferenceDay7 =>
      '一周：味觉和嗅觉回归\n\n来源：NHS Better Health\n\n达到一周不吸烟，是长期成功的有力预测因素——熬过第一周的人更有可能永久戒烟。\n\n已经恢复的\n• 食物的味道更有滋味\n• 气味更加鲜明\n• 呼吸更轻松——气道正在清理\n• 血液循环正在改善\n• 皮肤保水更好\n\n吸烟会直接损害味觉和嗅觉感受器；在停止后的数天内，它们开始恢复。\n\n急性尼古丁戒断正在缓解。身体渴求更短、更不频繁。由触发因素引起的渴求可能仍然存在，但最严重的身体紧迫感已经过去。';

  @override
  String get smokingReferenceDay14 =>
      '两周：血液循环改善\n\n来源：NHS Better Health\n\n在停止后的2–12周内，血液循环得到改善。尼古丁每吸一支烟都会使血管收缩；没有它，血管放松，血液流动更顺畅。\n\n这意味着什么\n• 流向手、脚和周围组织的血流改善\n• 许多人注意到手脚更暖和\n• 走路和爬楼梯开始感觉更轻松\n\n随着一氧化碳已经在第一天从血液中清除、血液循环现在也在改善，氧气更有效地到达肌肉。\n\n排列在气道上的纤毛正在恢复，并将积聚的黏液推出来。如果你咳嗽得比平时多，那是恢复的迹象，而不是倒退。';

  @override
  String get smokingReferenceDay30 =>
      '一个月：肺功能上升\n\n来源：NHS Better Health\n\n呼吸变得更容易，肺功能得到改善——在3到9个月的窗口期内最多提高10%。到一个月时，你已经深入那条恢复曲线。\n\n肺部正在发生什么\n• 纤毛已经重新生长，并在更有效地清除黏液\n• 气道炎症正在平息\n• 持续的吸烟者咳嗽正在消退\n• 运动耐量正在改善\n\n随着肺功能提高，任何咳嗽、喘息和呼吸问题都会改善。一个月是那条恢复曲线上一个有意义的节点。';

  @override
  String get smokingReferenceDay90 =>
      '三个月：心脏病发作风险下降\n\n来源：PMC——Cardiovascular Effects of Smoking and Cessation（2024）\n\n吸烟以多种方式损害心脏和动脉：它加速动脉斑块积聚、促进血液凝固、升高血压，并损害动脉内膜。促进凝血、促进血栓形成的效应在停止后的数天内逆转，这篇综述报告在戒烟的第一年内心脏病发作和中风出现显著下降。\n\n到现在已经改善的\n• 血液凝固因子正在正常化\n• 血压和心率正在稳定\n• 急性心血管事件风险最急剧的早期下降正在顺利进行\n\n作用较慢的益处——逆转多年动脉斑块的积聚——需要更长时间，将在后续里程碑中介绍。每一个不吸烟的月份都在为恢复添砖加瓦。';

  @override
  String get smokingReferenceDay180 =>
      '六个月：免疫防御恢复\n\n来源：Smoke-free period and recovery of alveolar immune-cell function（PubMed）\n\n吸烟会抑制肺部深处的免疫细胞，损害它们吞噬和杀灭细菌的能力。恢复是渐进的——那些仅戒断2个月的人受损最严重，而功能会随着更长的戒断稳步改善。到6个月时，肺部免疫防御已经大幅恢复。\n\n这意味着什么\n肺部能更有效地清除吸入的细菌和颗粒，降低对感冒、流感和肺炎的易感性。\n\n免疫防御会持续改善到六个月之后——但到现在，身体的保护力已经明显强于最初几周。';

  @override
  String get smokingReferenceDay365 =>
      '一年：心脏病发作风险大幅下降\n\n来源：PMC——Smoking Cessation and Stroke Outcome；CDC，Benefits of Quitting Smoking\n\n吸烟通过促进动脉斑块积聚、增加血液凝固、升高血压和损害脑血管，使中风风险大约翻倍。CDC自己的戒烟益处时间线将心脏病发作风险的急剧下降放在1到2年节点——你正处在这个窗口的前沿。\n\n恢复时间线\n中风风险的完全正常化需要更长时间：所引用的中风研究对戒烟者进行了中位数近五年的随访，才显示出比持续吸烟者有意义地更低的中风率，而CDC数据将冠心病风险减半放在3到6年，中风风险则在5到10年节点下降。\n\n一年仍然是一个真正的医学里程碑——急性风险下降最陡峭的部分已经在你身后，尽管更长期的心血管和癌症益处还会持续积累数年。';

  @override
  String get smokingReferenceDay1825 =>
      '五年：癌症风险下降\n\n来源：CDC，Benefits of Quitting Smoking\n\n到五年时，一些最显著的癌症益处到来了。\n\n五到十年的里程碑\n• 口腔、咽喉和声带癌的额外风险：减半\n• 中风风险：正在下降\n\n仍在前面\n• 十年：肺癌死亡风险大约减半（在10–15年后）；膀胱癌、食道癌和肾癌风险正在下降\n• 十五年：冠心病风险接近非吸烟者\n• 二十年：口腔、咽喉和声带癌风险接近非吸烟者水平；额外的宫颈癌风险大约减半\n\n五年不吸烟是一项真正的成就——你现在正处于一些最显著的癌症风险降低开始生效的窗口之内，尽管若干益处（如冠心病风险的完全正常化）仍在数年之外。';

  @override
  String get snriReferenceDay3 =>
      'SNRI停药：最初几天\n\n来源：哈佛健康出版社（Harvard Health Publishing）\n\n重要安全提示\nSNRI只能在医疗监督下通过逐步减量来停用。尤其是文拉法辛（Effexor），其半衰期极短，约为5小时，这意味着药物从体内清除得非常快，停药症状可能严重而突然。\n\n为什么SNRI比SSRI更难停用\nSNRI影响两种调节情绪的脑化学物质——血清素和去甲肾上腺素——这意味着停药时两者都需要重新调整。SNRI的停药症状往往比SSRI更强烈：\n• 流感样症状（疲劳、出汗、肌肉酸痛）\n• 失眠和睡眠紊乱\n• 恶心——往往比SSRI更明显\n• 失衡和头晕\n• 感觉障碍——文拉法辛的“脑闪”可能非常强烈\n• 过度唤起、易怒和焦虑\n\nSNRI之间的比较\n由于半衰期短，文拉法辛的停药特征最为困难。度洛西汀（Cymbalta）由于半衰期较长（12小时）而往往稍微容易一些。去甲文拉法辛介于两者之间。';

  @override
  String get snriReferenceDay7 =>
      '停用SNRI一周：两个脑化学系统在调整\n\n来源：NHS——Stopping or coming off antidepressants（一般抗抑郁药指导；下述去甲肾上腺素特异性机制反映的是一般SNRI药理学，而非NHS页面本身的SNRI特异性细节）\n\n双重系统的挑战\n与大多数只影响一个系统的抗抑郁药不同，SNRI同时影响血清素和去甲肾上腺素。到一周时，两个系统都在调整：\n\n去甲肾上腺素系统的影响\n去甲肾上腺素系统掌管身体的战斗或逃跑反应、血压调节和精力水平。随着它重新调整：\n• 可能出现血压波动\n• 焦虑可能感觉更偏身体层面（心跳加速、出汗）\n• 精力水平可能不稳定\n\n血清素系统的影响\n与此同时，血清素系统正在调整——产生任何抗抑郁药停用都会出现的典型戒断症状。两个系统同时调整，可能使第一周尤其具有挑战性。\n\n在身体上，这通常表现为血压稳定性改善、站立时头晕发作减少。在情绪上，情绪比30天时更多变，但已不再处于自由落体状态。';

  @override
  String get snriReferenceDay14 =>
      '停用SNRI两周：身体症状消退\n\n来源：Davies & Read（2019），Addictive Behaviors\n\n两周的状态\n对于大多数遵循正确减量的人来说，急性身体阶段到两周时已大体消退：\n• 脑闪显著减少或消失\n• 恶心和流感样症状已消退\n• 头晕和平衡问题正在改善\n• 随着去甲肾上腺素重新平衡，血压和心率正在稳定\n\n可能持续存在的\n• 情绪敏感和情绪多变\n• 焦虑——去甲肾上腺素系统尤其会影响这一点\n• 疲劳，因为去甲肾上腺素系统提供警觉和精力\n\n研究背景\nAddictive Behaviors的系统综述（Davies & Read，2019）确认，SNRI的停药效应是所有抗抑郁药类别中最严重的之一，文拉法辛与尤其高比例的显著戒断症状相关。';

  @override
  String get snriReferenceDay30 =>
      '停用SNRI一个月：双重系统稳定\n\n来源：Davies & Read（2019），Addictive Behaviors——关于抗抑郁药戒断发生率、严重程度和持续时间的系统综述\n\n稳定阶段\n一个月是血清素和去甲肾上腺素恢复的一个重要里程碑。这篇综述发现，虽然相当一部分少数人经历的戒断效应会持续超过几周，但到此时，大多数人都已远过急性、最严重的身体停药症状阶段。\n\n到一个月时通常会改善的\n• 身体停药症状（脑闪、恶心、头晕）对大多数人已消退\n• 血压回到自然水平\n• 睡眠质量改善——REM睡眠模式自然恢复\n• 随着去甲肾上腺素调节正常化，精力水平开始稳定\n\n情绪麻木的消退\n这一阶段最常被报告的体验之一是情绪麻木的消退——许多服用SNRI的人会注意到“扁平”的情绪范围。随着药物清除和大脑重新调整，情绪范围和敏感性通常会回归。';

  @override
  String get snriReferenceDay90 =>
      '停用SNRI三个月：早已度过戒断\n\n来源：《Antidepressant Withdrawal Syndrome》，Therapeutics Letter 112（2018），Therapeutics Initiative，见NCBI Bookshelf\n\n为什么SNRI值得格外小心\n这篇证据综述特别指出，短半衰期抗抑郁药——包括文拉法辛和度洛西汀（两者都是SNRI）——带有更高的戒断症状风险。一项由制造商资助的研究发现，51%停用度洛西汀的人出现了一种或多种症状。因此SNRI戒断可能很明显，这正是逐步、受监督的减量如此重要的原因。\n\n三个月处于什么位置\n该Letter指出，戒断症状“通常在停药后几天内出现”，“大多数抗抑郁药戒断症状在2周内消退”（偶尔更长）。到三个月时，急性戒断阶段对绝大多数人来说早已过去。\n\n关于“受体恢复”的恢复信号\n流行的说法声称血清素和去甲肾上腺素系统在三个月时已“完全重新平衡”。可靠的证据涉及戒断综合征及其时间，而非精确的受体恢复时钟。可以确信的是：到三个月时戒断阶段通常已经消退，许多人注意到在SNRI上感到的情绪麻木在停药后有所缓解。\n\n戒断与复发\n该Letter建议把戒断与基础疾病的真正复发区分开来。如果焦虑或情绪低落在三个月时持续存在，应与你的开药医生一起评估，而不是想当然地认为这只是戒断。';

  @override
  String get snriReferenceDay180 =>
      '停用SNRI六个月：大脑和神经恢复\n\n关于六个月数据的恢复信号\n到完成一次医疗监督下的减量六个月后，严重的早期SNRI戒断期早已在你身后。情绪、睡眠、性功能和清晰思维都有了数月的时间来恢复：\n• 血清素通路：基本恢复\n• 去甲肾上腺素通路：正常化，压力反应系统也在安定\n• 睡眠结构：预期已完全恢复\n• 性功能：对大多数人已大体恢复（性功能障碍是SNRI常见的副作用，尽管对有些人可能持续存在，值得与开药医生讨论）\n\n对压力的韧性\n许多人在六个月时报告对日常压力源的韧性明显改善，因为去甲肾上腺素系统在唤醒和压力反应中的作用——SNRI强有力地调节着这一点——回落到其自然水平。';

  @override
  String get snriReferenceDay365 =>
      '停用SNRI一年：恢复达成\n\n一年：一次完整的双重系统恢复\n在完成SNRI减量一年后，血清素和去甲肾上腺素系统都有了一个完整的周期来适应和稳定。\n\n证据在一年时实际支持什么\n这篇Therapeutics Letter综述指出，有记载的戒断症状“通常在停药后几天内出现”，大多数在大约两周内消退——没有对照研究专门在SNRI停药一年后对人们进行随访。在这个距离上，更广泛的临床图景所充分支持的是：\n• 完成正确减量并获得心理支持的人中，大多数保持良好\n• 表征SNRI使用的情绪麻木和性功能障碍，对大多数人已完全消退\n• 清晰的思维，包括SNRI所能提供的注意力益处，通过自然的大脑功能得以维持\n\n这一里程碑的意义\n成功停用SNRI——尤其是文拉法辛——是一项重要的成就。停药过程的强度，以及在医疗监督下管理它所需的投入，展示了非凡的韧性。';

  @override
  String get socialMediaReferenceDay1 =>
      '从社交媒体退后一步：第一天\n\n来源：Lambert et al.，《Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial》，Cyberpsychology, Behavior, and Social Networking（2022），见PubMed\n\n证据显示了什么\n在这项强有力的对照研究中，人们被随机分配为要么从Facebook、Instagram、Twitter和TikTok休息一周，要么照常使用。休息组在幸福感上显示出显著改善，抑郁和焦虑显著减少。这是真实、受控的证据，表明退后一步有帮助。\n\n证据显示了什么\n强迫性社交媒体使用与更低的情绪和更高的焦虑密切相关，随机试验显示，刻意减少使用可以在一周内改善幸福感，同时减少抑郁和焦虑。\n\n第一天：可以预期什么\n• 坐立不安和查看的冲动\n• “幻影”通知——感觉到并没有发生的震动\n• 随着你适应更少的持续刺激而产生的无聊\n这些是与习惯相关的正常感觉，而且是暂时的。认识到这种模式，是改变它的第一步。';

  @override
  String get socialMediaReferenceDay3 =>
      '停用社交媒体三天：焦虑和情绪\n\n来源：Lambert et al.，《Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial》，Cyberpsychology, Behavior, and Social Networking（2022），见PubMed\n\n为什么休息有助于情绪\n在这项对照试验中，被随机分配从社交媒体休息一周的人，到周末时焦虑和抑郁低于继续刷屏的人，幸福感则更高。大量使用的日常痛苦很多来自社会比较——用你的真实生活去对照别人精心策划的高光片段——以及错失恐惧（FOMO）那种低度的牵引。\n\n72小时前后会发生什么\n休息初期，习惯仍然很响：\n• 强烈的查看冲动，往往由例行时刻触发（醒来、排队等待）\n• 一些易怒和坐立不安\n• 对一些人来说，由比较驱动的焦虑第一次得到缓解\n• 睡前刷屏的习惯开始松动\n\n比较陷阱开始松动\n没有了源源不断的他人高光，助长社交媒体焦虑的比较就少了燃料。该试验的结果表明，到第一周结束时，这些早期转变累积成可测量的情绪改善——因此三天时的不适，是一次会带来回报的改变中艰难的部分。';

  @override
  String get socialMediaReferenceDay7 =>
      '停用社交媒体一周：可测量的回报\n\n来源：Lambert et al.，《Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial》，Cyberpsychology, Behavior, and Social Networking（2022），见PubMed\n\n正好一周——而且奏效了\n这是研究最直接对口的里程碑：该试验的干预就是一周的休息。与继续使用社交媒体的人相比，休息组在仅仅七天后就显示出显著更高的幸福感和显著更低的抑郁和焦虑。达到一周，就是达到了一项对照研究发现真实益处的时间点。\n\n人们通常注意到什么\n除了可测量的情绪收获之外，人们往往报告：\n• 更多被收回的时间——许多人惊讶于自己曾花了多少时间\n• 更容易专注，因为持续切换注意力的习惯松动了\n• 没有了睡前刷屏，夜晚更平静、睡眠更轻松\n这些收获与该试验所测量的更广泛的幸福感改善相符。\n\n继续下去\n一周是一个真实的、有证据支持的里程碑。情绪、时间和注意力的益处往往随着更健康的模式持续而加深。';

  @override
  String get socialMediaReferenceDay14 =>
      '停用社交媒体两周：两周的收获\n\n来源：Coyne & Woodruff，《Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults》，Behavioral Sciences（2023），见PubMed Central\n\n关于这项研究\n年轻成年人将社交媒体限制在每天约30分钟、持续两周，使用情况在手机上被客观追踪（下降了约78%）。参与者的社交媒体使用减少了约78%，为这个里程碑提供了一个关于急剧减少使用两周后会发生什么的直接真实世界测试。\n\n哪些改善了\n在两周里，参与者表现出以下方面的改善：\n• 睡眠——时长和质量都有\n• 生活满意度\n• 压力\n• 感知到的健康\n• 智能手机和社交媒体成瘾量表得分\n可测量的收获是具体的：更长更好的睡眠、更低的压力、更高的生活满意度和感知健康，以及更低的智能手机/社交媒体成瘾得分。\n\n留意倒退\n研究人员还注意到，之后使用量又悄悄回升到之前的水平。两周是一个真实的收获，但它凸显了为什么一个有意的计划——而不仅仅是一次暂时的休息——才是保持益处的原因。';

  @override
  String get socialMediaReferenceDay30 =>
      '停用社交媒体一个月：真实的联系加深\n\n来源：Coyne & Woodruff，《Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults》，Behavioral Sciences（2023），见PubMed Central\n\n当你退后一步时，联系可以改善\n这听起来矛盾——但在这项研究中，大幅削减社交媒体与支持性人际关系的改善相关，同时生活满意度更高、压力更低。原本流向信息流的时间和注意力，变得可以用来给那些真正在你生活中的人。\n\n一个月往往会带来什么\n到30天时，随着自动查看的牵引力大大减弱，许多人发现：\n• 对话更专注、更少被打断\n• 对现实世界活动和爱好更感兴趣\n• 自我形象更少依赖点赞、评论和粉丝数\n\n恢复信号\n到一个月时，你已经将这个更健康的模式维持了研究干预窗口的两倍时长。两周时测量到的睡眠、压力、生活满意度、健康和人际关系收获，又有了两周时间来巩固成习惯。\n\n让时间变得有价值\n目标是把你腾出的时间用在能建立真实联系和满足感的活动上，而不是仅仅把一块屏幕换成另一块。';

  @override
  String get socialMediaReferenceDay60 =>
      '停用社交媒体两个月：证据支持什么\n\n来源：Ramadhan et al.，《Impacts of digital social media detox for mental health: A systematic review and meta-analysis》，Narra J（2024），见PubMed Central\n\n最可靠的图景\n研究人员合并了10项研究的结果，包括七项对照试验。最清晰的结果是，人们在从社交媒体退后一步后，抑郁症状出现有意义的减少。\n\n最强的结果\n合并研究发现了抑郁症状的明确减少。到两个月时，你正在维持那种产生了心理健康益处的、同样较低的数字化暴露。\n\n两个月可能是什么样子\n随着每天更少的比较和更少由信息流驱动的强化，自我形象远没有理由依赖点赞、评论或粉丝数，而最强的合并证据指向更低的抑郁症状。\n\n实际要点\n证据奖励有意的、持续的改变。利用两个月这个节点，保持刻意的限制而不是悄悄退回，并投资于线下的意义和联系来源。';

  @override
  String get socialMediaReferenceDay90 =>
      '停用社交媒体三个月：一个新的常态\n\n来源：Coyne & Woodruff，《Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults》，Behavioral Sciences（2023），见PubMed Central\n\n睡眠是最突出的\n这项研究最清晰的发现之一，是参与者在大幅削减社交媒体后睡眠得到改善——时长和质量都有。到三个月的持续健康模式时，过去吞噬睡眠的深夜刷屏早已不再与休息竞争，而更好的睡眠往往也会随之提升情绪、专注力和精力。\n\n还有什么改善了\n同一项研究发现了压力、生活满意度、感知健康和支持性人际关系方面的收获。到三个月时，这些已不再是新奇事物——它们已经有了时间来沉淀成一个新的常态。\n\n关于机制的恢复信号\n在这项干预研究中，大幅削减社交媒体同时改善了睡眠时长和睡眠质量。维持这种模式三个月，把深夜刷屏的减少变成了一种持久的睡眠习惯。\n\n专注与关系\n随着用手机填满每个安静时刻的反射大大减弱，专注当下——在对话、用餐和闲暇时光中——变得更加自然，而你在三个月里投入的关系往往也因此感觉更牢固。';

  @override
  String get socialMediaReferenceDay180 =>
      '停用社交媒体六个月：可测量的恢复\n\n来源：Ramadhan et al.，《Impacts of digital social media detox for mental health: A systematic review and meta-analysis》，Narra J（2024），见PubMed Central\n\n荟萃分析补充了什么\n合并10项研究（包括七项对照试验），研究人员发现人们在减少或暂停社交媒体后抑郁症状出现明确减少。\n\n它实际发现了什么\n• 抑郁：统计学上显著的减少（最清晰、最一致的益处）\n• 生活满意度：无显著效应\n• 压力：无显著效应\n• 总体心理健康：无显著效应\n最强的合并结果是明确的：数字化脱毒显著减少抑郁症状。\n\n为什么你仍可能感受到广泛的益处\n六个月的减少信息流暴露，累积了较短干预中所见的实际收获：更多可用的时间、更少的强迫性查看，以及与抑郁症状相关的数字化暴露的持续减少。\n\n保持对信息流的掌控\n最大的收获来自打破大量、被动、强迫性的使用。到六个月时，对社交媒体有意的掌控已成为新的默认状态，而非信息流在掌控你的注意力。';

  @override
  String get socialMediaReferenceDay365 =>
      '停用社交媒体一年：一段重新协商的关系\n\n来源：Ramadhan et al.，《Impacts of digital social media detox for mental health: A systematic review and meta-analysis》，Narra J（2024），见PubMed Central\n\n一年的持续改变\n最强的合并研究显示，从社交媒体退后一步可以减少抑郁症状。整整一年意味着那种较低暴露的模式已经成为你的常态，而非一次短暂的休息。\n\n一年会建立什么\n整整一年为你腾出了数百个小时，用于真实的关系、爱好、技能、反思和创造力。自动查看有了整整一年来减弱，而那些线下的日常也有了整整一年来加强。\n\n持续的益处\n最清晰的可测量心理健康收获是更低的抑郁症状。实际的收获——更多时间、更少打断、更少强迫性查看——在你掌控信息流的每一天都在累积。\n\n接下来是什么\n一年的刻意改变已经重置了这段关系。无论你是回归有限的、有意的使用，还是彻底停用，强迫性的循环已经被打破——而那才是持久的胜利。';

  @override
  String get ssriReferenceDay3 =>
      'SSRI停药：最初几天\n\n来源：哈佛健康出版社（Harvard Health Publishing）\n\n重要安全提示\nSSRI只能在医疗监督下通过逐步减量来停用。突然停药——尤其是长期使用之后——会显著增加停药症状的严重程度。\n\n什么是SSRI停药综合征？\nSSRI停药综合征是一种有充分记载的医学现象，发生在SSRI被停止或大幅减量时。临床医生用首字母缩略词FINISH来描述常见症状：\n• 流感样症状（疲劳、出汗、肌肉酸痛）\n• 失眠和睡眠紊乱\n• 恶心\n• 失衡和头晕\n• 感觉障碍——尤其是“脑闪”\n• 过度唤起、易怒和焦虑\n\n半衰期很重要\n氟西汀（Prozac）半衰期很长，为4–6天，因此它实际上会自我减量，产生的停药效应较轻。帕罗西汀（Paxil）是常见SSRI中半衰期最短的，产生的停药症状最强烈。舍曲林、西酞普兰和艾司西酞普兰介于两者之间。';

  @override
  String get ssriReferenceDay7 =>
      '停用SSRI一周：急性期\n\n来源：NHS——Stopping or coming off antidepressants\n\n急性停药阶段\nNHS记载，大多数抗抑郁药停药症状在停止后的五天内开始，并在大多数情况下持续长达六周。到一周时，对于逐步减量的人来说，急性身体症状通常最为明显，并开始呈下降趋势。\n\n一周时可以预期什么\n• 身体症状（恶心、头晕、流感样感觉）最为强烈，但应开始缓解\n• 睡眠紊乱，包括生动的梦境或失眠，很常见\n• 情绪不稳定——快速的情绪变化——在这一阶段很常见\n• 脑闪可能仍然存在，但通常开始减少频率\n\n减量的作用\nNHS强烈建议缓慢减量——对长期使用者有时需要数月——以尽量减少停药效应。英国皇家精神科医学院制定了减量指南，建议对长期服用SSRI的人采用非常渐进的剂量减少，通常使用液体制剂。';

  @override
  String get ssriReferenceDay14 =>
      '停用SSRI两周：身体症状消退\n\n来源：Davies & Read（2019），Addictive Behaviors——\'A systematic review into the incidence, severity and duration of antidepressant withdrawal effects\'\n\n研究发现\n这项具有里程碑意义的系统综述发现，大约56%停用抗抑郁药的人会经历戒断效应，其中46%描述为严重。对于大多数遵循正确减量的人来说，急性期到两周时已大体消退：\n• 脑闪显著减少或消失\n• 恶心和流感样症状已消退\n• 头晕和平衡问题正在改善\n• 睡眠开始正常化\n\n区分停药与复发\n在停药后数天内出现、且符合FINISH特征的症状，最可能是停药综合征。在2–4周后出现、且类似于所治疗的原始疾病的症状，更可能是复发。与你的开药医生一起监测这一区分很重要。';

  @override
  String get ssriReferenceDay30 =>
      '停用SSRI一个月：稳定\n\n来源：Haddad PM（2001），Drug Safety——\'Antidepressant Discontinuation Syndromes\'\n\n稳定阶段\n这篇综述将停药发作描述为迅速的，通常在停止或减少抗抑郁药的数天内，并指出大多数反应是轻微的、短暂的，无需特定治疗即可消退。一个月代表着从那个急性窗口向稳定的过渡；对大多数完成逐步减量的人来说，急性停药症状现在已大体消退。\n\n一个月时的情绪图景\n一个月时的情绪变化是多变的，需要监测：\n• 有些人在大脑调整的初期感到情绪更“扁平”——这通常会改善\n• 其他人则体验到多年未曾感受到的情绪鲜明感\n• 焦虑水平因个体和基础疾病而有显著差异\n\n非药物支持的价值\n研究一致表明，诸如CBT（认知行为疗法）等谈话疗法和其他循证心理疗法，对SSRI所治疗的疾病非常有效。一个月节点是确保这些支持到位的好时机。';

  @override
  String get ssriReferenceDay90 =>
      '停用SSRI三个月：早已度过戒断\n\n来源：《Antidepressant Withdrawal Syndrome》，Therapeutics Letter 112（2018），Therapeutics Initiative，见NCBI Bookshelf\n\n三个月处于什么位置\n这篇证据综述指出，抗抑郁药戒断症状“通常在停止或减少剂量后几天内出现”，“大多数抗抑郁药戒断症状在2周内消退”——尽管严重病例可能持续数周到数月。到三个月时，急性戒断阶段对绝大多数人来说早已过去。\n\n为什么SSRI各不相同\n短半衰期SSRI（如帕罗西汀）比长半衰期SSRI（氟西汀）更可能出现戒断。该Letter坦率地指出，戒断反应可能相当严重——两项系统综述发现它们与苯二氮卓类药物的反应“非常相似”——并且至少出现在三分之一停用的人身上。\n\n关于“受体恢复”的恢复信号\n你可能会看到自信的说法，称血清素受体“在2–3个月时完全重新敏感化”。可靠的证据是关于戒断综合征及其时间的，而非精确的受体恢复时钟。可以确信的是：到三个月时戒断阶段通常已经消退，许多人注意到在SSRI上感到的情绪麻木和性副作用在停药后有所缓解。\n\n如果症状持续\n该Letter建议把戒断与基础疾病的真正复发区分开来。如果情绪低落或焦虑在三个月时持续存在，值得与你的开药医生一起评估，而非想当然地认为它“只是戒断”。';

  @override
  String get ssriReferenceDay180 =>
      '停用SSRI六个月：一个脚踏实地的视角\n\n来源：《Antidepressant Withdrawal Syndrome》，Therapeutics Letter 112（2018），Therapeutics Initiative，见NCBI Bookshelf\n\n到六个月时已被充分确立的\n这篇综述指出，即便是严重的、长期的戒断症状，通常也持续数周到数月而非无限期——因此到六个月时，对绝大多数人来说，急性戒断综合征已经明确消退。\n\n对剩下的部分坦诚\n到六个月时，通常的戒断期早已在你身后，血清素系统也有了数月的时间来安定。性副作用在停药后通常会改善；如果它们持续存在，与你的开药医生讨论。\n\n人们通常报告什么\n• 与服药期间相比更宽广的情绪范围\n• 对大多数人来说改善的睡眠和精力\n• 持续的渐进改善，尽管个体之间的速度差异很大';

  @override
  String get ssriReferenceDay365 =>
      '停用SSRI一年：可测量的恢复\n\n来源：Duffy et al.（2021），Health Technology Assessment——the ANTLER trial\n\n这项试验实际发现了什么\nANTLER在英国初级保健中随访了长期使用抗抑郁药的人，他们要么继续服药，要么停药。在接下来的一年里，停药的人中有56%复发，而继续服药的人中为39%——大约是两倍的风险——而且停药组平均报告的生活质量略低。\n\n更完整的图景\n尽管复发率更高，但相当一部分停药的人并未复发，并且在不用药的情况下保持良好。大约三分之一停药的人最终重新开始服用抗抑郁药——这是一个合理的临床选择，而非失败。\n\n关于未来的说明\n对一些人来说，抑郁和焦虑是慢性疾病。如果基础疾病重新显现，重新用药并不是失败。目标是健康幸福——无论接下来发生什么，成功停药一年都是一项真正的成就。';

  @override
  String get steroidsReferenceDay1 =>
      '停用合成代谢类固醇：最初几天\n\n来源：《Common symptoms associated with usage and cessation of anabolic androgenic steroids in men》，Best Practice & Research Clinical Endocrinology & Metabolism（2022）\n\n急性期\n这篇综述将合成代谢雄激素类固醇（AAS）的戒断描述为分两个阶段展开。第一阶段由交感神经系统激活驱动，而非激素水平，在停止后的1–2天内出现，可能包括：\n• 头痛\n• 震颤\n• 心悸\n• 恶心\n\n为什么会出现症状\n合成代谢类固醇还会抑制身体自身的睾酮产生——大脑检测到类固醇，并关闭了通常驱动它的激素信号。这种抑制在停止后持续存在，为后续里程碑中描述的第二个、更持久的戒断阶段埋下伏笔。\n\n安全提示\n抑郁可能在类固醇戒断期间出现，并变得严重。请寻求医疗护理，并对任何自伤念头寻求紧急帮助。临床医生常常引导恢复；有些人使用药物来支持这一过程。';

  @override
  String get steroidsReferenceDay14 =>
      '停用合成代谢类固醇两周\n\n来源：《Common symptoms associated with usage and cessation of anabolic androgenic steroids in men》，Best Practice & Research Clinical Endocrinology & Metabolism（2022）\n\n慢性阶段到来\n到两周时，最初几天的短暂交感神经症状通常已经过去，而综述中的第二阶段——由持续的睾酮缺乏驱动——更为突出：\n• 疲劳和情绪低落\n• 肌肉酸痛（肌痛）\n• 性欲减退\n• 失眠和渴求\n\n仍处于低谷\n自然睾酮产生所需的时间远不止两周，因此这一阶段是预期中的，而非出问题的迹象。\n\n一个已知的陷阱\n一些男性重新开始使用，正是为了逃避这段空窗期——这是一个让恢复时钟重置而非结束的循环。来自医生或咨询师的支持有助于渡过这一阶段，而不是用更多的类固醇来“自我用药”。';

  @override
  String get steroidsReferenceDay30 =>
      '停用合成代谢类固醇一个月\n\n来源：《Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review》，见PubMed\n\n恢复开始\n停止后，告诉睾丸制造睾酮的激素信号开始重新开启。研究将大部分恢复放在三到六个月的范围内，因此到一个月时，这一过程已经在进行。\n\n可以预期什么\n在激素回升期间，情绪低落、性欲和精力低下通常持续存在。恢复取决于年龄以及使用有多重、多长。';

  @override
  String get steroidsReferenceDay90 =>
      '停用合成代谢类固醇三个月\n\n来源：《Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review》，见PubMed\n\n一个做血液检测的好时机\n到三个月时，激素系统已经有时间显示出有意义的恢复。这是一个有用的时点，请你的全科医生检查睾酮和控制它的激素。\n\n可以预期什么\n对许多男性来说，三个月时水平正在攀升但尚未完全正常化。情绪和性欲往往在睾酮完全跟上之前就得到改善。睾丸大小和精子产生恢复得更慢，并可能在接下来的一年里持续改善。乳房组织增生（男性乳房发育），如果发生了，没有特定治疗不太可能逆转。';

  @override
  String get steroidsReferenceDay180 =>
      '停用合成代谢类固醇六个月\n\n来源：《Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review》，见PubMed\n\n证据指向哪里\n该综述报告，LH和FSH——告诉睾丸制造睾酮的激素——通常在大约三到六个月内恢复。到六个月时，睾酮本身也已经在恢复的道路上走了很远。\n\n如果你还没到那一步\n如果低睾酮症状在六个月时仍然存在，内分泌科医生可以检查发生了什么并讨论治疗，而不是让你干等。';

  @override
  String get steroidsReferenceDay365 =>
      '停用合成代谢类固醇一年\n\n来源：《Anabolic androgenic steroid-induced hypogonadism, a reversible condition in male individuals? A systematic review》，见PubMed\n\n一年无类固醇\n一年停用给了激素系统一个漫长的恢复窗口。睾酮、情绪、性欲、自然力量和心脏健康都有了充足的时间来恢复。\n\n长期图景\n如果低睾酮症状在一年时仍然存在，专科激素评估是正确的下一步。保持停用类固醇，能保护已经取得的恢复。';

  @override
  String get steroidsReferenceDay730 =>
      '停用合成代谢类固醇两年\n\n来源：《Anabolic androgenic steroid-induced hypogonadism, a reversible condition in male individuals? A systematic review》，见PubMed\n\n一个新的常态\n到两年时，你的激素水平反映了你身体的自然产生。对大多数恢复的男性来说，情绪、性欲、力量和动力在没有类固醇的情况下是稳定的。\n\n长期激素恢复\n研究显示睾酮会在数月内恢复，而向睾丸发出信号的激素通常在三到六个月内恢复。睾丸大小、精子产生和性欲可以在数月至数年内持续改善。到两年时，持续存在的低睾酮症状应交给专科医生，而不是再来一个类固醇周期。';

  @override
  String get tcaReferenceDay3 =>
      'TCA停药：最初几天——乙酰胆碱反弹\n\n来源：Dilsaver, Feinberg & Greden（1983），American Journal of Psychiatry——\'Antidepressant withdrawal symptoms treated with anticholinergic agents\'（病例报告，3名患者）\n\n是什么让TCA停药与众不同\n三环类抗抑郁药（TCA）在机制上与SSRI和SNRI根本不同。除了阻断血清素和去甲肾上腺素的再摄取之外，TCA还强烈阻断身体的乙酰胆碱系统。当你停止时，这个系统会反弹。\n\n乙酰胆碱反弹症状\n与SSRI停药不同，TCA戒断会产生乙酰胆碱反弹：\n• 恶心、呕吐和腹泻\n• 唾液和出汗过多\n• 头痛和肌肉酸痛\n• 伴有生动或令人不安梦境的失眠\n• 焦虑和坐立不安\n\n常见TCA及其特征\n阿米替林和丙咪嗪的乙酰胆碱阻断效应最强，通常产生最明显的反弹。去甲替林的效应稍微温和一些。氯米帕明除了其乙酰胆碱阻断特征之外，还有显著的血清素相关效应。';

  @override
  String get tcaReferenceDay7 =>
      '停用TCA一周：乙酰胆碱症状缓解\n\n乙酰胆碱的恢复\n乙酰胆碱反弹通常在最初几天达到高峰，到一周时开始大幅缓解。随着乙酰胆碱系统回到其自然水平：\n\n哪些在改善\n• 胃肠症状（恶心、痉挛、腹泻）正在减少\n• 出汗和流感样症状正在缓解\n• 睡眠虽然仍然紊乱，但开始稳定\n• 过多的唾液分泌正在消退\n\n自主神经系统\nTCA通过多种机制影响身体的自主功能——心率、血压、消化。到一周时，最强烈的自主神经症状——包括站立时头晕和心率的快速变化——随着神经系统的重新调整而开始消退。';

  @override
  String get tcaReferenceDay14 =>
      '停用TCA两周：抗乙酰胆碱效应正在逆转\n\n抗乙酰胆碱负担解除\nTCA对身体施加显著的乙酰胆碱阻断效应，影响多个系统。随着这种负担在最初两周内解除：\n\n身体上的益处\n• 口干消退——唾液腺功能恢复正常\n• 便秘消退——肠道蠕动自然恢复\n• 排尿功能正常化——TCA可能引起的尿潴留正在消退\n• 视力模糊清晰——眼睛再次正常地适应光线\n\n思维和记忆的益处\n乙酰胆碱对记忆、注意力和学习至关重要。被TCA抑制的乙酰胆碱通路正在恢复：\n• 工作记忆改善\n• 处理速度提高\n• 思维清晰度回归\n\n许多人对自己在服用TCA期间适应了多少脑雾和记忆问题感到惊讶。';

  @override
  String get tcaReferenceDay30 =>
      '停用TCA一个月：自主神经系统稳定\n\n心脏恢复\nTCA在使用期间通过作用于乙酰胆碱和肾上腺素相关的神经系统来影响心律。关于TCA停药的临床文献确认，急性戒断症状——包括由这种“乙酰胆碱和肾上腺素相关的过度驱动”所驱动的自主神经效应——通常是轻微的，并在停止后一到两周内消退。到一个月时，大多数人已经远过这个急性窗口，可以预期：\n• 心律回落到其用药前的起始水平\n• 心率变异性趋向自然水平\n• 此前受药物对肾上腺素通路作用影响的血压调节，持续稳定\n\n睡眠结构恢复\nTCA强烈抑制做梦睡眠。随着抗乙酰胆碱效应消退（做梦睡眠需要乙酰胆碱）：\n• REM睡眠正在回归，往往在梦睡眠回归时产生一阵生动的梦境\n• 慢波（深度）睡眠正在改善\n• 总体睡眠质量和恢复明显好于使用TCA期间';

  @override
  String get tcaReferenceDay90 =>
      '停用TCA三个月：把真正的风险抛在身后\n\n证据显示了什么\n一项2024年对103项随机试验（10,590名参与者）的荟萃分析发现，与安慰剂相比，TCA确实能减少抑郁症状——但严重不良事件的几率也接近三倍（比值比2.78）。这些试验本身只对人们进行了最多12周的治疗期随访，因此没有关于停止后会发生什么的对照长期数据。下面的一切反映的是对TCA药理学的一般临床理解，而非这项试验证据的具体发现。\n\n多系统恢复\nTCA影响的脑化学系统范围比SSRI或SNRI更广：\n• 血清素系统：调整中\n• 去甲肾上腺素系统：调整中\n• 乙酰胆碱系统：回落到正常\n• 组胺系统：抗组胺样的镇静作用已经消退\n\n到三个月时，所有这些系统都有了充足的时间来恢复，而且——同样重要的是——伴随活跃TCA治疗的升高的严重不良事件风险已经在你身后。许多人注意到：\n• 清晰的思维改善——尤其是记忆和注意力\n• 更好的情绪稳定性\n• 精力和动力改善\n• 镇静减少、警觉性改善';

  @override
  String get tcaReferenceDay180 =>
      '停用TCA六个月：心脏和思维恢复\n\n关于长期数据的恢复信号\nTCA停药后的早期戒断期通常是轻微的，并在一到两周内消退。到一次受监督减量后六个月时，TCA对心率、记忆和思维的影响已经有了数月的时间来恢复。\n\n心血管恢复\n到六个月时，TCA对心律的直接作用应该早已消退：\n• 无需药物驱动的影响即可维持正常心律\n• 心率变异性（衡量你的心脏适应能力好坏的指标）预期已大幅改善\n• 站立时头晕完全消退\n\n思维和记忆恢复\nTCA通过阻断乙酰胆碱可能引起脑雾和记忆问题，尤其是在老年人中。这些效应在停药后会改善。到六个月时：\n• 记忆巩固大幅改善\n• 处理速度正常化\n• 计划、工作记忆以及在任务或想法之间切换的能力都有意义的恢复';

  @override
  String get tcaReferenceDay365 =>
      '停用TCA一年：恢复达成\n\n一年：完整的多系统恢复\n这篇关于抗抑郁药停药综合征的综述——涵盖TCA、MAOI、SSRI等——发现戒断症状通常在停止后的数天内开始，若不治疗，会在数天到几周内自行消退。没有研究专门在一年后重新测量受TCA影响的系统，但在完成减量一年后，已经比哪怕是最长的已报告停药症状都要晚好几个月，因此所有受影响的脑化学系统——血清素、去甲肾上腺素、乙酰胆碱和组胺——都可以预期已经有了一个完整的周期来正常化。\n\nTCA恢复的意义\nTCA施加的药物驱动负担比新型抗抑郁药更广，同时影响更多的受体系统。成功停药代表着多个系统的恢复：\n• TCA乙酰胆碱阻断造成的记忆和思维损害被完全逆转\n• 心脏完全恢复\n• 所有受影响的通路上都恢复了自然的脑化学调节\n\n在TCA停药后成功自我调节一年，是一项真正的成就——无论是在停药过程的管理上，还是在无需药物驱动支持的情况下维持健康幸福上。';
}
